CREATE OR REPLACE FUNCTION public.accept_staff_invite_by_code(code text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  invite public.staff_invites;
  new_profile public.profiles;
  user_email text;
begin
  if auth.uid() is null then
    raise exception 'Login required';
  end if;

  if exists (select 1 from public.profiles where id = auth.uid()) then
    raise exception 'This user already belongs to a clinic';
  end if;

  user_email := auth.jwt() ->> 'email';

  select *
  into invite
  from public.staff_invites
  where upper(invite_code) = upper(trim(code))
    and accepted_at is null
    and cancelled_at is null
  order by created_at desc
  limit 1;

  if invite.id is null then
    raise exception 'No pending invite found for this code';
  end if;

  if invite.email is not null and lower(invite.email) <> lower(coalesce(user_email, '')) then
    raise exception 'This invite code is assigned to a different email';
  end if;

  insert into public.profiles (id, clinic_id, name, email, role, active)
  values (auth.uid(), invite.clinic_id, invite.name, coalesce(user_email, invite.email), invite.role, true)
  returning * into new_profile;

  update public.staff_invites
  set accepted_at = now()
  where id = invite.id;

  return new_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_dental_chart_correction(p_visit_id uuid, p_tooth_code text, p_dentition text, p_condition text, p_surfaces text[], p_notes text, p_treatment_name text, p_treatment_status text, p_reason text)
 RETURNS dental_chart_entries
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_visit public.patient_visits;
  v_previous public.dental_chart_entries;
  v_new public.dental_chart_entries;
  v_tooth_code text;
  v_dentition text;
  v_condition text;
  v_treatment_status text;
  v_surfaces text[];
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can add chart corrections.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A chart correction reason is required.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();
  v_tooth_code := trim(coalesce(p_tooth_code, ''));
  v_dentition := lower(trim(coalesce(p_dentition, '')));
  v_condition := lower(trim(coalesce(p_condition, '')));
  v_treatment_status := lower(trim(coalesce(p_treatment_status, '')));

  select * into v_visit
  from public.patient_visits
  where id = p_visit_id
    and clinic_id = v_clinic_id;

  if not found then
    raise exception 'Visit was not found in your clinic.' using errcode = 'P0002';
  end if;

  if v_dentition not in ('permanent', 'primary') then
    raise exception 'Invalid dentition.' using errcode = '22023';
  end if;

  if not (
    (v_dentition = 'permanent' and v_tooth_code ~ '^[1-4][1-8]$')
    or (v_dentition = 'primary' and v_tooth_code ~ '^[5-8][1-5]$')
  ) then
    raise exception 'Invalid FDI tooth code for the selected dentition.' using errcode = '22023';
  end if;

  if v_condition not in (
    'healthy', 'caries', 'filled', 'missing', 'crown',
    'root_canal', 'implant', 'extraction_planned', 'unerupted'
  ) then
    raise exception 'Invalid dental condition.' using errcode = '22023';
  end if;

  if v_treatment_status not in ('planned', 'ongoing', 'completed') then
    raise exception 'Invalid chart treatment status.' using errcode = '22023';
  end if;

  if char_length(coalesce(p_notes, '')) > 1000
     or char_length(coalesce(p_treatment_name, '')) > 160 then
    raise exception 'Chart notes or treatment name are too long.' using errcode = '22023';
  end if;

  select coalesce(array_agg(distinct surface), '{}'::text[])
  into v_surfaces
  from unnest(coalesce(p_surfaces, '{}'::text[])) as item(surface);

  if not (v_surfaces <@ array['mesial','distal','occlusal','buccal','lingual']::text[])
     or cardinality(v_surfaces) > 5 then
    raise exception 'Invalid dental surface.' using errcode = '22023';
  end if;

  select * into v_previous
  from public.dental_chart_entries
  where clinic_id = v_clinic_id
    and patient_id = v_visit.patient_id
    and tooth_code = v_tooth_code
    and dentition = v_dentition
  order by created_at desc, id desc
  limit 1;

  insert into public.dental_chart_entries (
    clinic_id, patient_id, visit_id, recorded_by, tooth_code, dentition,
    condition, surfaces, notes, treatment_name, treatment_status
  ) values (
    v_clinic_id, v_visit.patient_id, p_visit_id, auth.uid(), v_tooth_code, v_dentition,
    v_condition, v_surfaces, nullif(trim(coalesce(p_notes, '')), ''),
    nullif(trim(coalesce(p_treatment_name, '')), ''), v_treatment_status
  ) returning * into v_new;

  insert into public.clinical_audit_logs (
    clinic_id, patient_id, visit_id, target_type, target_id,
    changed_by, action, field_name, old_value, new_value, reason
  ) values (
    v_clinic_id,
    v_visit.patient_id,
    p_visit_id,
    'dental_chart_entry',
    v_new.id,
    auth.uid(),
    'chart_correction_added',
    concat(v_dentition, ':', v_tooth_code),
    case when v_previous.id is null then null else jsonb_build_object(
      'entry_id', v_previous.id,
      'condition', v_previous.condition,
      'surfaces', v_previous.surfaces,
      'treatment_name', v_previous.treatment_name,
      'treatment_status', v_previous.treatment_status,
      'notes', v_previous.notes
    )::text end,
    jsonb_build_object(
      'entry_id', v_new.id,
      'condition', v_new.condition,
      'surfaces', v_new.surfaces,
      'treatment_name', v_new.treatment_name,
      'treatment_status', v_new.treatment_status,
      'notes', v_new.notes
    )::text,
    trim(p_reason)
  );

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_apply_invoice_discount(p_invoice_id uuid, p_amount numeric, p_reason text, p_notes text DEFAULT NULL::text)
 RETURNS invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old public.invoices;
  v_new public.invoices;
  v_adjustment_id uuid;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can apply discounts.' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A discount reason is required.' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Discount amount must be greater than zero.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();
  select * into v_old
  from public.invoices
  where id = p_invoice_id and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Invoice was not found in your clinic.' using errcode = 'P0002';
  end if;
  if p_amount > v_old.due_amount + 0.01 then
    raise exception 'Discount cannot exceed the current outstanding amount.' using errcode = '22023';
  end if;

  update public.invoices
  set total_amount = total_amount - p_amount,
      discount_amount = discount_amount + p_amount,
      updated_at = now(),
      updated_by = auth.uid()
  where id = p_invoice_id;

  v_new := public.recalculate_invoice_financials(p_invoice_id);

  insert into public.financial_adjustments (
    clinic_id, patient_id, invoice_id, adjustment_type, amount,
    old_values, new_values, reason, notes, created_by
  ) values (
    v_clinic_id,
    v_old.patient_id,
    v_old.id,
    'discount',
    p_amount,
    to_jsonb(v_old),
    to_jsonb(v_new),
    trim(p_reason),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  ) returning id into v_adjustment_id;

  perform public.append_invoice_version(p_invoice_id, 'discount', v_adjustment_id, p_reason);
  select * into v_new from public.invoices where id = p_invoice_id;
  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_cancel_staff_invite(p_invite_id uuid, p_reason text)
 RETURNS staff_invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor public.profiles;
  v_invite public.staff_invites;
begin
  select * into v_actor
  from public.profiles
  where id = auth.uid() and active = true;

  if v_actor.id is null or v_actor.role not in ('owner','head_doctor') then
    raise exception 'Only the clinic owner or head doctor can cancel staff invitations.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'A cancellation reason is required.' using errcode = '22023';
  end if;

  select * into v_invite
  from public.staff_invites
  where id = p_invite_id
    and clinic_id = v_actor.clinic_id
    and accepted_at is null
    and cancelled_at is null
  for update;

  if not found then
    raise exception 'Pending invitation was not found.' using errcode = 'P0002';
  end if;

  update public.staff_invites
  set cancelled_at = now(),
      cancelled_by = auth.uid(),
      cancellation_reason = trim(p_reason)
  where id = p_invite_id
  returning * into v_invite;

  insert into public.management_audit_logs
    (clinic_id, target_type, target_id, changed_by, action, field_name, old_value, new_value, reason)
  values
    (v_actor.clinic_id, 'staff_invite', v_invite.id, auth.uid(), 'cancelled', 'status', 'pending', 'cancelled', trim(p_reason));

  return v_invite;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_correct_payment(p_payment_id uuid, p_amount numeric, p_payment_method text, p_payment_category text, p_notes text, p_paid_at timestamp with time zone, p_reason text)
 RETURNS payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old_payment public.payments;
  v_new_payment public.payments;
  v_old_invoice public.invoices;
  v_new_invoice public.invoices;
  v_other_net numeric;
  v_adjustment_id uuid;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can correct payments.' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A correction reason is required.' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Corrected payment amount must be greater than zero.' using errcode = '22023';
  end if;
  if p_payment_category not in ('op_fee', 'xray_fee', 'medication_fee', 'treatment_fee', 'pending_collection', 'other') then
    raise exception 'Invalid payment category.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_payment_method, '')), '') is null then
    raise exception 'Payment method is required.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select * into v_old_payment
  from public.payments
  where id = p_payment_id and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Payment was not found in your clinic.' using errcode = 'P0002';
  end if;
  if v_old_payment.status not in ('active', 'corrected') or v_old_payment.amount <= 0 then
    raise exception 'Only an active positive payment can be corrected.' using errcode = '22023';
  end if;

  select * into v_old_invoice
  from public.invoices
  where id = v_old_payment.invoice_id and clinic_id = v_clinic_id
  for update;

  select coalesce(sum(amount), 0)
  into v_other_net
  from public.payments
  where invoice_id = v_old_payment.invoice_id
    and id <> v_old_payment.id
    and status in ('active', 'corrected', 'refund');

  if v_other_net + p_amount < 0 or v_other_net + p_amount > v_old_invoice.total_amount + 0.01 then
    raise exception 'Corrected payment would make the invoice balance invalid.' using errcode = '22023';
  end if;

  update public.payments
  set
    amount = p_amount,
    payment_method = trim(p_payment_method),
    payment_category = p_payment_category,
    notes = nullif(trim(coalesce(p_notes, '')), ''),
    created_at = coalesce(p_paid_at, created_at),
    status = 'corrected',
    updated_at = now(),
    updated_by = auth.uid()
  where id = p_payment_id
  returning * into v_new_payment;

  v_new_invoice := public.recalculate_invoice_financials(v_old_payment.invoice_id);

  insert into public.financial_adjustments (
    clinic_id, patient_id, invoice_id, payment_id, adjustment_type, amount,
    old_values, new_values, reason, notes, created_by
  ) values (
    v_clinic_id,
    v_old_payment.patient_id,
    v_old_payment.invoice_id,
    v_old_payment.id,
    'payment_correction',
    abs(p_amount - v_old_payment.amount),
    jsonb_build_object('payment', to_jsonb(v_old_payment), 'invoice', to_jsonb(v_old_invoice)),
    jsonb_build_object('payment', to_jsonb(v_new_payment), 'invoice', to_jsonb(v_new_invoice)),
    trim(p_reason),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  ) returning id into v_adjustment_id;

  perform public.append_invoice_version(v_old_payment.invoice_id, 'payment_correction', v_adjustment_id, p_reason);
  return v_new_payment;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_appointment(p_patient_id uuid, p_doctor_id uuid, p_appointment_time timestamp with time zone, p_notes text, p_reason text)
 RETURNS appointments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_appointment public.appointments;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can create appointments from Clinic Admin.' using errcode = '42501';
  end if;

  if p_appointment_time is null then
    raise exception 'Appointment date and time are required.' using errcode = '22023';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A creation reason is required.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  if not exists (
    select 1 from public.patients
    where id = p_patient_id
      and clinic_id = v_clinic_id
      and archived_at is null
  ) then
    raise exception 'The selected active patient was not found in your clinic.' using errcode = 'P0002';
  end if;

  if p_doctor_id is not null and not exists (
    select 1 from public.profiles
    where id = p_doctor_id
      and clinic_id = v_clinic_id
      and active = true
      and role in ('owner', 'head_doctor', 'doctor', 'working_doctor')
  ) then
    raise exception 'The selected doctor is not active in your clinic.' using errcode = '22023';
  end if;

  insert into public.appointments (
    clinic_id,
    patient_id,
    doctor_id,
    appointment_time,
    status,
    notes,
    created_by,
    updated_by
  )
  values (
    v_clinic_id,
    p_patient_id,
    p_doctor_id,
    p_appointment_time,
    'scheduled',
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid(),
    auth.uid()
  )
  returning * into v_appointment;

  insert into public.appointment_audit_logs (
    clinic_id, appointment_id, changed_by, action, field_name, old_value, new_value, reason
  ) values (
    v_clinic_id,
    v_appointment.id,
    auth.uid(),
    'created',
    'appointment',
    null,
    concat('patient=', p_patient_id::text, '; doctor=', coalesce(p_doctor_id::text, 'unassigned'), '; time=', p_appointment_time::text, '; status=scheduled'),
    trim(p_reason)
  );

  return v_appointment;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_staff_invite(p_name text, p_email text, p_role text, p_reason text)
 RETURNS staff_invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor public.profiles;
  v_invite public.staff_invites;
begin
  select * into v_actor
  from public.profiles
  where id = auth.uid() and active = true;

  if v_actor.id is null or v_actor.role not in ('owner','head_doctor') then
    raise exception 'Only the clinic owner or head doctor can invite staff.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'An invitation reason is required.' using errcode = '22023';
  end if;

  if length(trim(coalesce(p_name,''))) < 2 then
    raise exception 'Staff name is required.' using errcode = '22023';
  end if;

  select * into v_invite
  from public.create_staff_invite(trim(p_name), nullif(lower(trim(coalesce(p_email,''))), ''), p_role);

  update public.staff_invites
  set cancelled_at = null,
      cancelled_by = null,
      cancellation_reason = null
  where id = v_invite.id
  returning * into v_invite;

  insert into public.management_audit_logs
    (clinic_id, target_type, target_id, changed_by, action, field_name, old_value, new_value, reason)
  values
    (v_actor.clinic_id, 'staff_invite', v_invite.id, auth.uid(), 'created', 'invite', null,
     concat('name=', v_invite.name, '; role=', v_invite.role, '; email=', coalesce(v_invite.email,'not restricted')),
     trim(p_reason));

  return v_invite;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_get_release_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_result jsonb;
begin
  if not public.current_user_is_owner() then
    raise exception 'Release health is available only to owners and head doctors.' using errcode = '42501';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  with payment_totals as (
    select
      i.id as invoice_id,
      i.total_amount,
      i.paid_amount,
      i.due_amount,
      coalesce(sum(case when coalesce(p.status, 'active') <> 'voided' then p.amount else 0 end), 0) as effective_paid
    from public.invoices i
    left join public.payments p on p.invoice_id = i.id and p.clinic_id = i.clinic_id
    where i.clinic_id = v_clinic_id
    group by i.id, i.total_amount, i.paid_amount, i.due_amount
  )
  select jsonb_build_object(
    'checked_at', now(),
    'clinic_id', v_clinic_id,
    'client_errors_24h', (
      select count(*) from public.admin_client_error_logs
      where clinic_id = v_clinic_id and created_at >= now() - interval '24 hours'
    ),
    'client_errors_7d', (
      select count(*) from public.admin_client_error_logs
      where clinic_id = v_clinic_id and created_at >= now() - interval '7 days'
    ),
    'last_client_error_at', (
      select max(created_at) from public.admin_client_error_logs where clinic_id = v_clinic_id
    ),
    'active_staff', (
      select count(*) from public.profiles where clinic_id = v_clinic_id and active = true
    ),
    'invoice_count', (
      select count(*) from public.invoices where clinic_id = v_clinic_id
    ),
    'payment_count', (
      select count(*) from public.payments where clinic_id = v_clinic_id
    ),
    'paid_total_mismatches', (
      select count(*) from payment_totals where round(paid_amount::numeric, 2) <> round(effective_paid::numeric, 2)
    ),
    'due_total_mismatches', (
      select count(*) from payment_totals where round(due_amount::numeric, 2) <> round(greatest(total_amount - effective_paid, 0)::numeric, 2)
    )
  ) into v_result;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_record_report_export(p_report_type text, p_export_format text, p_period_start date, p_period_end date, p_row_count integer)
 RETURNS report_export_logs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_saved public.report_export_logs;
  v_type text := lower(trim(coalesce(p_report_type, '')));
  v_format text := lower(trim(coalesce(p_export_format, '')));
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can export administrative reports.' using errcode = '42501';
  end if;
  if v_type not in ('monthly_summary', 'patients', 'appointments', 'clinical', 'gallery', 'payments', 'invoices', 'staff_activity', 'audit', 'archived_records') then
    raise exception 'Unsupported report type.' using errcode = '22023';
  end if;
  if v_format not in ('csv', 'excel', 'pdf', 'print') then
    raise exception 'Unsupported export format.' using errcode = '22023';
  end if;
  if coalesce(p_row_count, 0) < 0 then
    raise exception 'Row count cannot be negative.' using errcode = '22023';
  end if;
  v_clinic_id := public.current_user_clinic_id();
  insert into public.report_export_logs (
    clinic_id, exported_by, report_type, export_format, period_start, period_end, row_count
  ) values (
    v_clinic_id, auth.uid(), v_type, v_format, p_period_start, p_period_end, coalesce(p_row_count, 0)
  ) returning * into v_saved;
  return v_saved;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_refund_payment(p_payment_id uuid, p_amount numeric, p_refund_method text, p_notes text, p_reason text)
 RETURNS payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_original public.payments;
  v_refund public.payments;
  v_old_invoice public.invoices;
  v_new_invoice public.invoices;
  v_refunded numeric;
  v_adjustment_id uuid;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can issue refunds.' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A refund reason is required.' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Refund amount must be greater than zero.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_refund_method, '')), '') is null then
    raise exception 'Refund method is required.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select * into v_original
  from public.payments
  where id = p_payment_id and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Payment was not found in your clinic.' using errcode = 'P0002';
  end if;
  if v_original.status not in ('active', 'corrected') or v_original.amount <= 0 then
    raise exception 'Only an active positive payment can be refunded.' using errcode = '22023';
  end if;

  select * into v_old_invoice
  from public.invoices
  where id = v_original.invoice_id and clinic_id = v_clinic_id
  for update;

  select coalesce(-sum(amount), 0)
  into v_refunded
  from public.payments
  where original_payment_id = v_original.id
    and status = 'refund';

  if p_amount > v_original.amount - v_refunded + 0.01 then
    raise exception 'Refund exceeds the refundable amount for this payment.' using errcode = '22023';
  end if;
  if p_amount > v_old_invoice.paid_amount + 0.01 then
    raise exception 'Refund exceeds the effective amount paid on this invoice.' using errcode = '22023';
  end if;

  insert into public.payments (
    clinic_id, invoice_id, patient_id, amount, payment_method, notes,
    payment_category, collected_by, status, original_payment_id, updated_by
  ) values (
    v_clinic_id,
    v_original.invoice_id,
    v_original.patient_id,
    -p_amount,
    trim(p_refund_method),
    coalesce(nullif(trim(coalesce(p_notes, '')), ''), 'Clinic Admin refund'),
    v_original.payment_category,
    auth.uid(),
    'refund',
    v_original.id,
    auth.uid()
  ) returning * into v_refund;

  update public.invoices
  set refunded_amount = refunded_amount + p_amount
  where id = v_original.invoice_id;

  v_new_invoice := public.recalculate_invoice_financials(v_original.invoice_id);

  insert into public.financial_adjustments (
    clinic_id, patient_id, invoice_id, payment_id, related_payment_id,
    adjustment_type, amount, old_values, new_values, reason, notes, created_by
  ) values (
    v_clinic_id,
    v_original.patient_id,
    v_original.invoice_id,
    v_original.id,
    v_refund.id,
    'refund',
    p_amount,
    jsonb_build_object('payment', to_jsonb(v_original), 'invoice', to_jsonb(v_old_invoice)),
    jsonb_build_object('refund_payment', to_jsonb(v_refund), 'invoice', to_jsonb(v_new_invoice)),
    trim(p_reason),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  ) returning id into v_adjustment_id;

  perform public.append_invoice_version(v_original.invoice_id, 'refund', v_adjustment_id, p_reason);
  return v_refund;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_file_archived(p_file_id uuid, p_archived boolean, p_reason text)
 RETURNS files
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor public.profiles;
  v_file public.files;
  v_reason text := trim(coalesce(p_reason, ''));
begin
  select * into v_actor from public.profiles where id = auth.uid() and active = true limit 1;
  if v_actor.id is null or v_actor.clinic_id is null then raise exception using errcode = '42501', message = 'Active clinic profile not found'; end if;
  if v_actor.role not in ('owner', 'head_doctor') then raise exception using errcode = '42501', message = 'Only the clinic owner or head doctor can archive gallery files'; end if;
  if char_length(v_reason) < 3 then raise exception 'A reason of at least 3 characters is required'; end if;
  select * into v_file from public.files where id = p_file_id and clinic_id = v_actor.clinic_id for update;
  if v_file.id is null then raise exception 'Gallery file not found in the active clinic'; end if;
  if (p_archived and v_file.archived_at is not null) or (not p_archived and v_file.archived_at is null) then return v_file; end if;
  perform set_config('capdent.file_archive_rpc', 'on', true);
  update public.files set archived_at = case when p_archived then now() else null end, archived_by = case when p_archived then v_actor.id else null end, archive_reason = case when p_archived then v_reason else null end where id = v_file.id returning * into v_file;
  insert into public.file_audit_logs (clinic_id, patient_id, file_id, changed_by, action, old_value, new_value, reason)
  values (v_actor.clinic_id, v_file.patient_id, v_file.id, v_actor.id, case when p_archived then 'archive' else 'restore' end, jsonb_build_object('archived', not p_archived), jsonb_build_object('archived', p_archived), v_reason);
  return v_file;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_patient_archived(p_patient_id uuid, p_archived boolean, p_reason text)
 RETURNS patients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_old public.patients;
  v_new public.patients;
  v_clinic_id uuid;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can archive patient records.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'An archive or restore reason is required.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select *
  into v_old
  from public.patients
  where id = p_patient_id
    and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Patient was not found in your clinic.' using errcode = 'P0002';
  end if;

  update public.patients
  set
    archived_at = case when p_archived then now() else null end,
    archived_by = case when p_archived then auth.uid() else null end,
    archive_reason = case when p_archived then trim(p_reason) else null end,
    updated_at = now(),
    updated_by = auth.uid()
  where id = p_patient_id
  returning * into v_new;

  if (v_old.archived_at is null) is distinct from (v_new.archived_at is null) then
    insert into public.patient_audit_logs
      (clinic_id, patient_id, changed_by, field_name, old_value, new_value, reason)
    values
      (
        v_clinic_id,
        p_patient_id,
        auth.uid(),
        'archive_status',
        case when v_old.archived_at is null then 'active' else 'archived' end,
        case when v_new.archived_at is null then 'active' else 'archived' end,
        trim(p_reason)
      );
  end if;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_appointment(p_appointment_id uuid, p_patient_id uuid, p_doctor_id uuid, p_appointment_time timestamp with time zone, p_status text, p_notes text, p_reason text)
 RETURNS appointments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old public.appointments;
  v_new public.appointments;
  v_status text;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can modify appointments.' using errcode = '42501';
  end if;

  if p_appointment_time is null then
    raise exception 'Appointment date and time are required.' using errcode = '22023';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A modification reason is required.' using errcode = '22023';
  end if;

  v_status := lower(trim(coalesce(p_status, '')));
  if v_status not in ('scheduled', 'waiting', 'completed', 'cancelled', 'no_show') then
    raise exception 'Unsupported appointment status.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select * into v_old
  from public.appointments
  where id = p_appointment_id
    and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Appointment was not found in your clinic.' using errcode = 'P0002';
  end if;

  if not exists (
    select 1 from public.patients
    where id = p_patient_id
      and clinic_id = v_clinic_id
  ) then
    raise exception 'The selected patient was not found in your clinic.' using errcode = 'P0002';
  end if;

  if p_doctor_id is not null and not exists (
    select 1 from public.profiles
    where id = p_doctor_id
      and clinic_id = v_clinic_id
      and active = true
      and role in ('owner', 'head_doctor', 'doctor', 'working_doctor')
  ) then
    raise exception 'The selected doctor is not active in your clinic.' using errcode = '22023';
  end if;

  update public.appointments
  set
    patient_id = p_patient_id,
    doctor_id = p_doctor_id,
    appointment_time = p_appointment_time,
    status = v_status,
    notes = nullif(trim(coalesce(p_notes, '')), ''),
    reminder_status = case
      when v_old.appointment_time is distinct from p_appointment_time then 'pending'
      else reminder_status
    end,
    reminder_sent_at = case
      when v_old.appointment_time is distinct from p_appointment_time then null
      else reminder_sent_at
    end,
    reminder_status_at = case
      when v_old.appointment_time is distinct from p_appointment_time then now()
      else reminder_status_at
    end,
    updated_at = now(),
    updated_by = auth.uid()
  where id = p_appointment_id
  returning * into v_new;

  insert into public.appointment_audit_logs (
    clinic_id, appointment_id, changed_by, action, field_name, old_value, new_value, reason
  )
  select
    v_clinic_id,
    p_appointment_id,
    auth.uid(),
    case changed.field_name
      when 'appointment_time' then 'rescheduled'
      when 'status' then 'status_changed'
      when 'doctor_id' then 'doctor_changed'
      when 'patient_id' then 'patient_changed'
      else 'updated'
    end,
    changed.field_name,
    changed.old_value,
    changed.new_value,
    trim(p_reason)
  from (
    values
      ('patient_id', v_old.patient_id::text, v_new.patient_id::text),
      ('doctor_id', v_old.doctor_id::text, v_new.doctor_id::text),
      ('appointment_time', v_old.appointment_time::text, v_new.appointment_time::text),
      ('status', v_old.status::text, v_new.status::text),
      ('notes', v_old.notes::text, v_new.notes::text)
  ) as changed(field_name, old_value, new_value)
  where changed.old_value is distinct from changed.new_value;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_clinic_settings(p_name text, p_phone text, p_email text, p_address text, p_brand_color text, p_opening_time time without time zone, p_closing_time time without time zone, p_op_fee_amount numeric, p_enable_patient_photos boolean, p_enable_prescription_medications boolean, p_payment_push_enabled boolean, p_tooth_chart_enabled boolean, p_reason text)
 RETURNS clinics
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor public.profiles;
  v_old public.clinics;
  v_new public.clinics;
begin
  select * into v_actor
  from public.profiles
  where id = auth.uid() and active = true;

  if v_actor.id is null or v_actor.role not in ('owner','head_doctor') then
    raise exception 'Only the clinic owner or head doctor can change clinic settings.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'A settings-change reason is required.' using errcode = '22023';
  end if;
  if length(trim(coalesce(p_name,''))) < 2 then
    raise exception 'Clinic name is required.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(p_email,'')), '') is not null
     and trim(p_email) !~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' then
    raise exception 'Enter a valid clinic email.' using errcode = '22023';
  end if;
  if p_brand_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Brand colour must use six-digit hex format.' using errcode = '22023';
  end if;
  if p_opening_time is null or p_closing_time is null or p_opening_time >= p_closing_time then
    raise exception 'Closing time must be after opening time.' using errcode = '22023';
  end if;
  if coalesce(p_op_fee_amount,0) < 0 or p_op_fee_amount > 1000000 then
    raise exception 'OP fee amount is outside the supported range.' using errcode = '22023';
  end if;

  select * into v_old
  from public.clinics
  where id = v_actor.clinic_id
  for update;

  update public.clinics
  set name = trim(p_name),
      phone = nullif(trim(coalesce(p_phone,'')), ''),
      email = nullif(lower(trim(coalesce(p_email,''))), ''),
      address = nullif(trim(coalesce(p_address,'')), ''),
      brand_color = upper(p_brand_color),
      opening_time = p_opening_time,
      closing_time = p_closing_time,
      op_fee_amount = p_op_fee_amount,
      enable_patient_photos = coalesce(p_enable_patient_photos,false),
      enable_prescription_medications = coalesce(p_enable_prescription_medications,false),
      payment_push_enabled = coalesce(p_payment_push_enabled,false),
      tooth_chart_enabled = coalesce(p_tooth_chart_enabled,false)
  where id = v_actor.clinic_id
  returning * into v_new;

  insert into public.management_audit_logs
    (clinic_id, target_type, target_id, changed_by, action, field_name, old_value, new_value, reason)
  select v_actor.clinic_id, 'clinic', v_actor.clinic_id, auth.uid(), 'settings_changed',
         changed.field_name, changed.old_value, changed.new_value, trim(p_reason)
  from (values
    ('name', v_old.name::text, v_new.name::text),
    ('phone', v_old.phone::text, v_new.phone::text),
    ('email', v_old.email::text, v_new.email::text),
    ('address', v_old.address::text, v_new.address::text),
    ('brand_color', v_old.brand_color::text, v_new.brand_color::text),
    ('opening_time', v_old.opening_time::text, v_new.opening_time::text),
    ('closing_time', v_old.closing_time::text, v_new.closing_time::text),
    ('op_fee_amount', v_old.op_fee_amount::text, v_new.op_fee_amount::text),
    ('enable_patient_photos', v_old.enable_patient_photos::text, v_new.enable_patient_photos::text),
    ('enable_prescription_medications', v_old.enable_prescription_medications::text, v_new.enable_prescription_medications::text),
    ('payment_push_enabled', v_old.payment_push_enabled::text, v_new.payment_push_enabled::text),
    ('tooth_chart_enabled', v_old.tooth_chart_enabled::text, v_new.tooth_chart_enabled::text)
  ) as changed(field_name, old_value, new_value)
  where changed.old_value is distinct from changed.new_value;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_clinical_treatment(p_treatment_id uuid, p_treatment_name text, p_description text, p_category text, p_status text, p_reason text)
 RETURNS treatments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old public.treatments;
  v_new public.treatments;
  v_status text;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can modify treatments.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A treatment modification reason is required.' using errcode = '22023';
  end if;

  if length(trim(coalesce(p_treatment_name, ''))) = 0
     or char_length(trim(p_treatment_name)) > 160 then
    raise exception 'Treatment name is required and must be at most 160 characters.' using errcode = '22023';
  end if;

  if char_length(coalesce(p_description, '')) > 2000
     or char_length(coalesce(p_category, '')) > 120 then
    raise exception 'Treatment description or category is too long.' using errcode = '22023';
  end if;

  v_status := lower(trim(coalesce(p_status, '')));
  if v_status not in ('planned', 'ongoing', 'completed') then
    raise exception 'Treatment status must be planned, ongoing or completed.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select * into v_old
  from public.treatments
  where id = p_treatment_id
    and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Treatment was not found in your clinic.' using errcode = 'P0002';
  end if;

  update public.treatments
  set
    treatment_name = trim(p_treatment_name),
    description = nullif(trim(coalesce(p_description, '')), ''),
    category = nullif(trim(coalesce(p_category, '')), ''),
    status = v_status,
    updated_at = now(),
    updated_by = auth.uid()
  where id = p_treatment_id
  returning * into v_new;

  insert into public.clinical_audit_logs (
    clinic_id, patient_id, visit_id, target_type, target_id,
    changed_by, action, field_name, old_value, new_value, reason
  )
  select
    v_clinic_id,
    v_old.patient_id,
    v_old.visit_id,
    'treatment',
    p_treatment_id,
    auth.uid(),
    case when changed.field_name = 'status' then 'treatment_status_changed' else 'treatment_updated' end,
    changed.field_name,
    changed.old_value,
    changed.new_value,
    trim(p_reason)
  from (
    values
      ('treatment_name', v_old.treatment_name::text, v_new.treatment_name::text),
      ('description', v_old.description::text, v_new.description::text),
      ('category', v_old.category::text, v_new.category::text),
      ('status', v_old.status::text, v_new.status::text)
  ) as changed(field_name, old_value, new_value)
  where changed.old_value is distinct from changed.new_value;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_clinical_visit(p_visit_id uuid, p_doctor_id uuid, p_visit_date timestamp with time zone, p_chief_complaint text, p_diagnosis text, p_doctor_notes text, p_next_appointment_date timestamp with time zone, p_reason text)
 RETURNS patient_visits
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old public.patient_visits;
  v_new public.patient_visits;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can modify clinical visits.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A clinical modification reason is required.' using errcode = '22023';
  end if;

  if p_visit_date is null then
    raise exception 'Visit date is required.' using errcode = '22023';
  end if;

  if char_length(coalesce(p_chief_complaint, '')) > 2000
     or char_length(coalesce(p_diagnosis, '')) > 2000
     or char_length(coalesce(p_doctor_notes, '')) > 4000 then
    raise exception 'One or more clinical text fields exceed the allowed length.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select * into v_old
  from public.patient_visits
  where id = p_visit_id
    and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Visit was not found in your clinic.' using errcode = 'P0002';
  end if;

  if p_doctor_id is not null and not exists (
    select 1
    from public.profiles
    where id = p_doctor_id
      and clinic_id = v_clinic_id
      and active = true
      and role in ('owner', 'head_doctor', 'doctor', 'working_doctor')
  ) then
    raise exception 'The selected doctor is not active in your clinic.' using errcode = '22023';
  end if;

  update public.patient_visits
  set
    doctor_id = p_doctor_id,
    visit_date = p_visit_date,
    chief_complaint = nullif(trim(coalesce(p_chief_complaint, '')), ''),
    diagnosis = nullif(trim(coalesce(p_diagnosis, '')), ''),
    doctor_notes = nullif(trim(coalesce(p_doctor_notes, '')), ''),
    next_appointment_date = p_next_appointment_date,
    updated_at = now(),
    updated_by = auth.uid()
  where id = p_visit_id
  returning * into v_new;

  insert into public.clinical_audit_logs (
    clinic_id, patient_id, visit_id, target_type, target_id,
    changed_by, action, field_name, old_value, new_value, reason
  )
  select
    v_clinic_id,
    v_old.patient_id,
    p_visit_id,
    'visit',
    p_visit_id,
    auth.uid(),
    case when changed.field_name = 'doctor_id' then 'doctor_reassigned' else 'visit_updated' end,
    changed.field_name,
    changed.old_value,
    changed.new_value,
    trim(p_reason)
  from (
    values
      ('doctor_id', v_old.doctor_id::text, v_new.doctor_id::text),
      ('visit_date', v_old.visit_date::text, v_new.visit_date::text),
      ('chief_complaint', v_old.chief_complaint::text, v_new.chief_complaint::text),
      ('diagnosis', v_old.diagnosis::text, v_new.diagnosis::text),
      ('doctor_notes', v_old.doctor_notes::text, v_new.doctor_notes::text),
      ('next_appointment_date', v_old.next_appointment_date::text, v_new.next_appointment_date::text)
  ) as changed(field_name, old_value, new_value)
  where changed.old_value is distinct from changed.new_value;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_staff_member(p_staff_id uuid, p_name text, p_phone text, p_role text, p_active boolean, p_reason text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor public.profiles;
  v_old public.profiles;
  v_new public.profiles;
  v_role text;
begin
  select * into v_actor
  from public.profiles
  where id = auth.uid() and active = true;

  if v_actor.id is null or v_actor.role not in ('owner','head_doctor') then
    raise exception 'Only the clinic owner or head doctor can manage staff.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_reason,''))) < 3 then
    raise exception 'A modification reason is required.' using errcode = '22023';
  end if;

  if p_staff_id = auth.uid() then
    raise exception 'You cannot change your own administrator access.' using errcode = '42501';
  end if;

  select * into v_old
  from public.profiles
  where id = p_staff_id and clinic_id = v_actor.clinic_id
  for update;

  if not found then
    raise exception 'Staff member was not found in your clinic.' using errcode = 'P0002';
  end if;

  if v_old.role = 'owner' then
    raise exception 'Clinic owner access cannot be changed here.' using errcode = '42501';
  end if;

  if v_actor.role = 'head_doctor' and v_old.role = 'head_doctor' then
    raise exception 'Only the clinic owner can modify another head doctor.' using errcode = '42501';
  end if;

  v_role := case when p_role = 'doctor' then 'working_doctor' else p_role end;
  if v_role not in ('head_doctor','working_doctor','receptionist') then
    raise exception 'Invalid staff role.' using errcode = '22023';
  end if;

  if v_role = 'head_doctor' and v_actor.role <> 'owner' then
    raise exception 'Only the clinic owner can assign the head-doctor role.' using errcode = '42501';
  end if;

  if length(trim(coalesce(p_name,''))) < 2 then
    raise exception 'Staff name is required.' using errcode = '22023';
  end if;

  update public.profiles
  set name = trim(p_name),
      phone = nullif(trim(coalesce(p_phone,'')), ''),
      role = v_role,
      active = coalesce(p_active, active)
  where id = p_staff_id
  returning * into v_new;

  if v_old.name is not distinct from v_new.name
     and v_old.phone is not distinct from v_new.phone
     and v_old.role is not distinct from v_new.role
     and v_old.active is not distinct from v_new.active then
    raise exception 'No staff changes were detected.' using errcode = '22023';
  end if;

  insert into public.management_audit_logs
    (clinic_id, target_type, target_id, changed_by, action, field_name, old_value, new_value, reason)
  select v_actor.clinic_id, 'staff', p_staff_id, auth.uid(),
         case when changed.field_name = 'active' then 'access_changed' else 'updated' end,
         changed.field_name, changed.old_value, changed.new_value, trim(p_reason)
  from (values
    ('name', v_old.name::text, v_new.name::text),
    ('phone', v_old.phone::text, v_new.phone::text),
    ('role', v_old.role::text, v_new.role::text),
    ('active', v_old.active::text, v_new.active::text)
  ) as changed(field_name, old_value, new_value)
  where changed.old_value is distinct from changed.new_value;

  if v_old.active and not v_new.active then
    update public.device_push_tokens
    set active = false,
        disabled_at = now(),
        updated_at = now(),
        last_error = 'Staff access deactivated by clinic administrator'
    where clinic_id = v_actor.clinic_id
      and user_id = p_staff_id
      and active = true;
  end if;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_void_payment(p_payment_id uuid, p_reason text, p_notes text DEFAULT NULL::text)
 RETURNS payments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old_payment public.payments;
  v_new_payment public.payments;
  v_old_invoice public.invoices;
  v_new_invoice public.invoices;
  v_adjustment_id uuid;
  v_type text;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can void financial entries.' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A void reason is required.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();

  select * into v_old_payment
  from public.payments
  where id = p_payment_id and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Payment was not found in your clinic.' using errcode = 'P0002';
  end if;
  if v_old_payment.status = 'voided' then
    raise exception 'This financial entry is already voided.' using errcode = '22023';
  end if;

  select * into v_old_invoice
  from public.invoices
  where id = v_old_payment.invoice_id and clinic_id = v_clinic_id
  for update;

  v_type := case when v_old_payment.status = 'refund' then 'refund_void' else 'payment_void' end;

  update public.payments
  set amount = 0,
      status = 'voided',
      notes = coalesce(nullif(trim(coalesce(p_notes, '')), ''), notes),
      updated_at = now(),
      updated_by = auth.uid()
  where id = p_payment_id
  returning * into v_new_payment;

  if v_old_payment.status = 'refund' then
    update public.invoices
    set refunded_amount = greatest(refunded_amount - abs(v_old_payment.amount), 0)
    where id = v_old_payment.invoice_id;
  end if;

  v_new_invoice := public.recalculate_invoice_financials(v_old_payment.invoice_id);

  insert into public.financial_adjustments (
    clinic_id, patient_id, invoice_id, payment_id, adjustment_type, amount,
    old_values, new_values, reason, notes, created_by
  ) values (
    v_clinic_id,
    v_old_payment.patient_id,
    v_old_payment.invoice_id,
    v_old_payment.id,
    v_type,
    abs(v_old_payment.amount),
    jsonb_build_object('payment', to_jsonb(v_old_payment), 'invoice', to_jsonb(v_old_invoice)),
    jsonb_build_object('payment', to_jsonb(v_new_payment), 'invoice', to_jsonb(v_new_invoice)),
    trim(p_reason),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  ) returning id into v_adjustment_id;

  perform public.append_invoice_version(v_old_payment.invoice_id, v_type, v_adjustment_id, p_reason);
  return v_new_payment;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_waive_invoice_due(p_invoice_id uuid, p_amount numeric, p_reason text, p_notes text DEFAULT NULL::text)
 RETURNS invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_old public.invoices;
  v_new public.invoices;
  v_adjustment_id uuid;
begin
  if not public.current_user_is_owner() then
    raise exception 'Only the clinic owner or head doctor can waive outstanding balances.' using errcode = '42501';
  end if;
  if length(trim(coalesce(p_reason, ''))) < 3 then
    raise exception 'A waiver reason is required.' using errcode = '22023';
  end if;
  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Waiver amount must be greater than zero.' using errcode = '22023';
  end if;

  v_clinic_id := public.current_user_clinic_id();
  select * into v_old
  from public.invoices
  where id = p_invoice_id and clinic_id = v_clinic_id
  for update;

  if not found then
    raise exception 'Invoice was not found in your clinic.' using errcode = 'P0002';
  end if;
  if p_amount > v_old.due_amount + 0.01 then
    raise exception 'Waiver cannot exceed the current outstanding amount.' using errcode = '22023';
  end if;

  update public.invoices
  set total_amount = total_amount - p_amount,
      waived_amount = waived_amount + p_amount,
      updated_at = now(),
      updated_by = auth.uid()
  where id = p_invoice_id;

  v_new := public.recalculate_invoice_financials(p_invoice_id);

  insert into public.financial_adjustments (
    clinic_id, patient_id, invoice_id, adjustment_type, amount,
    old_values, new_values, reason, notes, created_by
  ) values (
    v_clinic_id,
    v_old.patient_id,
    v_old.id,
    'waiver',
    p_amount,
    to_jsonb(v_old),
    to_jsonb(v_new),
    trim(p_reason),
    nullif(trim(coalesce(p_notes, '')), ''),
    auth.uid()
  ) returning id into v_adjustment_id;

  perform public.append_invoice_version(p_invoice_id, 'waiver', v_adjustment_id, p_reason);
  select * into v_new from public.invoices where id = p_invoice_id;
  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_dms_clinic_isolation_policy(p_table_name text, p_clinic_column text DEFAULT 'clinic_id'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  policy_name text := 'dms_clinic_isolation_' || p_table_name;
begin
  if to_regclass('public.' || p_table_name) is null then
    return;
  end if;

  execute format('alter table public.%I enable row level security', p_table_name);

  execute format(
    'drop policy if exists %I on public.%I',
    policy_name,
    p_table_name
  );

  execute format(
    'create policy %I on public.%I as restrictive for all to authenticated using (%I = public.current_profile_clinic_id()) with check (%I = public.current_profile_clinic_id())',
    policy_name,
    p_table_name,
    p_clinic_column,
    p_clinic_column
  );
end;
$function$

