CREATE OR REPLACE FUNCTION public.collect_reception_fee(p_patient_id uuid, p_fee_type text, p_amount numeric, p_payment_method text, p_notes text)
 RETURNS TABLE(invoice_id uuid, payment_id uuid, amount numeric, fee_type text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_clinic_id uuid;
  v_role text;
  v_patient_clinic_id uuid;
  v_invoice_id uuid;
  v_payment_id uuid;
  v_amount numeric;
  v_remaining numeric;
  v_apply_amount numeric;
  v_new_paid numeric;
  v_fee_type text;
  v_payment_category text;
  v_invoice record;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select pr.clinic_id, pr.role
  into v_clinic_id, v_role
  from public.profiles pr
  where pr.id = v_user_id
    and pr.active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Clinic not found for current user';
  end if;

  if v_role not in ('owner', 'head_doctor', 'receptionist') then
    raise exception 'Only owner or reception can collect fees';
  end if;

  select pt.clinic_id
  into v_patient_clinic_id
  from public.patients pt
  where pt.id = p_patient_id
  limit 1;

  if v_patient_clinic_id is null then
    raise exception 'Patient not found';
  end if;

  if v_patient_clinic_id <> v_clinic_id then
    raise exception 'Patient does not belong to your clinic';
  end if;

  v_fee_type := lower(trim(coalesce(p_fee_type, 'op_fee')));

  if v_fee_type = 'consultation_fee' then
    v_fee_type := 'op_fee';
  end if;

  if v_fee_type not in ('op_fee', 'medication_fee', 'xray_fee', 'treatment_fee', 'other') then
    v_fee_type := 'other';
  end if;

  v_payment_category := v_fee_type;
  v_amount := coalesce(p_amount, case when v_fee_type = 'op_fee' then 300 else 0 end);

  if v_amount <= 0 then
    raise exception 'Amount must be greater than zero';
  end if;

  v_remaining := v_amount;

  -- First apply collection to existing pending invoices in the same category.
  for v_invoice in
    select i.id,
           coalesce(i.total_amount, 0) as total_amount,
           coalesce(i.paid_amount, 0) as paid_amount,
           coalesce(i.due_amount, 0) as due_amount
    from public.invoices i
    where i.clinic_id = v_clinic_id
      and i.patient_id = p_patient_id
      and i.payment_category = v_payment_category
      and coalesce(i.due_amount, 0) > 0
      and i.status in ('unpaid', 'partial')
    order by i.created_at asc, i.id asc
  loop
    exit when v_remaining <= 0;

    v_apply_amount := least(v_remaining, v_invoice.due_amount);
    v_new_paid := least(v_invoice.total_amount, v_invoice.paid_amount + v_apply_amount);

    update public.invoices
    set paid_amount = v_new_paid,
        due_amount = greatest(v_invoice.total_amount - v_new_paid, 0),
        status = case when greatest(v_invoice.total_amount - v_new_paid, 0) <= 0 then 'paid' else 'partial' end
    where id = v_invoice.id;

    insert into public.payments (
      clinic_id,
      patient_id,
      invoice_id,
      amount,
      payment_method,
      notes,
      payment_category,
      collected_by
    )
    values (
      v_clinic_id,
      p_patient_id,
      v_invoice.id,
      v_apply_amount,
      coalesce(nullif(trim(p_payment_method), ''), 'Cash'),
      coalesce(nullif(trim(p_notes), ''), 'Pending fee collection'),
      v_payment_category,
      v_user_id
    )
    returning id into v_payment_id;

    invoice_id := v_invoice.id;
    payment_id := v_payment_id;
    amount := v_apply_amount;
    fee_type := v_fee_type;
    return next;

    v_remaining := v_remaining - v_apply_amount;
  end loop;

  -- If there is no old pending balance, or the collected amount is more than old due,
  -- create a normal paid invoice for the remaining amount.
  if v_remaining > 0 then
    insert into public.invoices (
      clinic_id,
      patient_id,
      total_amount,
      paid_amount,
      due_amount,
      status,
      invoice_type,
      payment_category,
      notes
    )
    values (
      v_clinic_id,
      p_patient_id,
      v_remaining,
      v_remaining,
      0,
      'paid',
      v_fee_type,
      v_payment_category,
      coalesce(nullif(trim(p_notes), ''), v_fee_type)
    )
    returning id into v_invoice_id;

    insert into public.payments (
      clinic_id,
      patient_id,
      invoice_id,
      amount,
      payment_method,
      notes,
      payment_category,
      collected_by
    )
    values (
      v_clinic_id,
      p_patient_id,
      v_invoice_id,
      v_remaining,
      coalesce(nullif(trim(p_payment_method), ''), 'Cash'),
      coalesce(nullif(trim(p_notes), ''), v_fee_type),
      v_payment_category,
      v_user_id
    )
    returning id into v_payment_id;

    invoice_id := v_invoice_id;
    payment_id := v_payment_id;
    amount := v_remaining;
    fee_type := v_fee_type;
    return next;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_owner_clinic(clinic_name text, owner_name text, clinic_phone text DEFAULT NULL::text, clinic_email text DEFAULT NULL::text, clinic_address text DEFAULT NULL::text, clinic_country_code text DEFAULT 'IN'::text, clinic_currency_code text DEFAULT 'INR'::text, clinic_opening_time time without time zone DEFAULT '09:00:00'::time without time zone, clinic_closing_time time without time zone DEFAULT '21:00:00'::time without time zone)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_clinic_id uuid;
  new_profile public.profiles;
  user_email text;
  clean_country_code text;
  clean_currency_code text;
begin
  if auth.uid() is null then
    raise exception 'Login required';
  end if;

  if nullif(trim(clinic_name), '') is null then
    raise exception 'Clinic name is required';
  end if;

  if nullif(trim(owner_name), '') is null then
    raise exception 'Owner name is required';
  end if;

  if exists (select 1 from public.profiles where id = auth.uid()) then
    raise exception 'This user already belongs to a clinic';
  end if;

  clean_country_code := upper(coalesce(nullif(trim(clinic_country_code), ''), 'IN'));
  clean_currency_code := upper(coalesce(nullif(trim(clinic_currency_code), ''), 'INR'));

  if clean_country_code !~ '^[A-Z]{2}$' then
    raise exception 'Invalid clinic country code';
  end if;

  if clean_currency_code !~ '^[A-Z]{3}$' then
    raise exception 'Invalid clinic currency code';
  end if;

  user_email := coalesce(nullif(auth.jwt() ->> 'email', ''), nullif(trim(clinic_email), ''));

  insert into public.clinics (
    name,
    phone,
    email,
    address,
    country_code,
    currency_code,
    opening_time,
    closing_time
  )
  values (
    trim(clinic_name),
    nullif(trim(clinic_phone), ''),
    coalesce(nullif(trim(clinic_email), ''), user_email),
    nullif(trim(clinic_address), ''),
    clean_country_code,
    clean_currency_code,
    coalesce(clinic_opening_time, '09:00'::time),
    coalesce(clinic_closing_time, '21:00'::time)
  )
  returning id into new_clinic_id;

  insert into public.clinic_subscriptions (
    clinic_id,
    plan_name,
    status,
    trial_started_at,
    trial_ends_at,
    current_period_start,
    current_period_end,
    monthly_price,
    visit_limit,
    billing_provider,
    google_play_status,
    google_play_auto_renewing
  )
  values (
    new_clinic_id,
    'free',
    'free',
    null,
    null,
    null,
    null,
    0,
    null,
    'manual',
    'not_started',
    false
  )
  on conflict (clinic_id) do nothing;

  insert into public.profiles (id, clinic_id, name, email, role, active)
  values (auth.uid(), new_clinic_id, trim(owner_name), user_email, 'owner', true)
  returning * into new_profile;

  return new_profile;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_patient_followup_reminder(p_patient_id uuid, p_appointment_time timestamp with time zone, p_notes text DEFAULT 'Follow-up reminder'::text)
 RETURNS appointments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_clinic_id uuid;
  v_patient_clinic_id uuid;
  v_row public.appointments;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select clinic_id
  into v_clinic_id
  from public.profiles
  where id = v_user_id
    and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Clinic not found for current user';
  end if;

  select clinic_id
  into v_patient_clinic_id
  from public.patients
  where id = p_patient_id
  limit 1;

  if v_patient_clinic_id is null then
    raise exception 'Patient not found';
  end if;

  if v_patient_clinic_id <> v_clinic_id then
    raise exception 'Patient does not belong to your clinic';
  end if;

  if p_appointment_time <= now() then
    raise exception 'Follow-up time must be in the future';
  end if;

  insert into public.appointments (
    clinic_id,
    patient_id,
    appointment_time,
    status,
    notes
  )
  values (
    v_clinic_id,
    p_patient_id,
    p_appointment_time,
    'scheduled',
    coalesce(nullif(trim(coalesce(p_notes, '')), ''), 'Follow-up reminder')
  )
  returning * into v_row;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_staff_invite(invitee_name text, invitee_email text DEFAULT NULL::text, invitee_role text DEFAULT 'working_doctor'::text)
 RETURNS staff_invites
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  owner_profile public.profiles;
  saved_invite public.staff_invites;
  normalized_role text;
  clean_email text;
  new_invite_code text;
begin
  select *
  into owner_profile
  from public.profiles
  where id = auth.uid()
    and active = true
  limit 1;

  if owner_profile.id is null then
    raise exception 'Profile not found for current user';
  end if;

  if owner_profile.role not in ('owner', 'head_doctor') then
    raise exception 'Only the clinic owner can invite staff';
  end if;

  normalized_role := case
    when invitee_role = 'doctor' then 'working_doctor'
    else invitee_role
  end;

  if normalized_role not in ('working_doctor', 'receptionist') then
    raise exception 'Staff role must be working_doctor or receptionist';
  end if;

  clean_email := nullif(lower(trim(coalesce(invitee_email, ''))), '');

  if clean_email is not null and exists (
    select 1
    from public.profiles
    where clinic_id = owner_profile.clinic_id
      and lower(email) = clean_email
  ) then
    raise exception 'This staff email already belongs to your clinic';
  end if;

  loop
    new_invite_code := 'DMS-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    exit when not exists (
      select 1 from public.staff_invites where invite_code = new_invite_code
    );
  end loop;

  if clean_email is not null then
    insert into public.staff_invites (
      clinic_id,
      email,
      name,
      role,
      invited_by,
      accepted_at,
      invite_code
    )
    values (
      owner_profile.clinic_id,
      clean_email,
      trim(invitee_name),
      normalized_role,
      owner_profile.id,
      null,
      new_invite_code
    )
    on conflict (clinic_id, email) do update
    set
      name = excluded.name,
      role = excluded.role,
      invited_by = excluded.invited_by,
      accepted_at = null,
      invite_code = excluded.invite_code,
      created_at = now()
    returning * into saved_invite;
  else
    insert into public.staff_invites (
      clinic_id,
      email,
      name,
      role,
      invited_by,
      accepted_at,
      invite_code
    )
    values (
      owner_profile.clinic_id,
      null,
      trim(invitee_name),
      normalized_role,
      owner_profile.id,
      null,
      new_invite_code
    )
    returning * into saved_invite;
  end if;

  return saved_invite;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_patient_file(p_file_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller public.profiles;
  target_file public.files;
begin
  select * into caller
  from public.profiles
  where id = auth.uid()
    and active = true
  limit 1;

  if caller.id is null or caller.clinic_id is null then
    raise exception 'Clinic profile not found';
  end if;

  if caller.role not in ('owner', 'head_doctor', 'doctor', 'working_doctor', 'receptionist') then
    raise exception 'You do not have permission to delete files';
  end if;

  select * into target_file
  from public.files
  where id = p_file_id
    and clinic_id = caller.clinic_id
  limit 1;

  if target_file.id is null then
    return false;
  end if;

  delete from public.files
  where id = p_file_id
    and clinic_id = caller.clinic_id;

  return true;
end;
$function$

