CREATE OR REPLACE FUNCTION public.get_capdent_ai_metrics(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_clinic_id uuid;
  v_role text;
  v_from date := least(coalesce(p_from, timezone('Asia/Kolkata', now())::date), coalesce(p_to, timezone('Asia/Kolkata', now())::date));
  v_to date := greatest(coalesce(p_from, timezone('Asia/Kolkata', now())::date), coalesce(p_to, timezone('Asia/Kolkata', now())::date));
  v_result jsonb;
begin
  if v_user_id is null then raise exception 'Not authenticated'; end if;

  select clinic_id, role into v_clinic_id, v_role
  from public.profiles
  where id = v_user_id and active = true
  limit 1;

  if v_clinic_id is null then raise exception 'Clinic not found for current user'; end if;
  if (v_to - v_from) > 366 then raise exception 'Date range cannot exceed 366 days'; end if;

  select jsonb_build_object(
    'from', v_from,
    'to', v_to,
    'role', v_role,
    'new_patients', (select count(*) from public.patients p where p.clinic_id=v_clinic_id and p.archived_at is null and timezone('Asia/Kolkata',p.created_at)::date between v_from and v_to),
    'appointments', (select count(*) from public.appointments a where a.clinic_id=v_clinic_id and timezone('Asia/Kolkata',a.appointment_time)::date between v_from and v_to),
    'appointments_completed', (select count(*) from public.appointments a where a.clinic_id=v_clinic_id and timezone('Asia/Kolkata',a.appointment_time)::date between v_from and v_to and lower(coalesce(a.status,'')) in ('completed','done')),
    'appointments_cancelled', (select count(*) from public.appointments a where a.clinic_id=v_clinic_id and timezone('Asia/Kolkata',a.appointment_time)::date between v_from and v_to and lower(coalesce(a.status,''))='cancelled'),
    'visits', (select count(*) from public.patient_visits v where v.clinic_id=v_clinic_id and timezone('Asia/Kolkata',v.visit_date)::date between v_from and v_to),
    'treatments', (select count(*) from public.treatments t where t.clinic_id=v_clinic_id and timezone('Asia/Kolkata',t.created_at)::date between v_from and v_to),
    'treatments_completed', (select count(*) from public.treatments t where t.clinic_id=v_clinic_id and timezone('Asia/Kolkata',t.created_at)::date between v_from and v_to and lower(coalesce(t.status,''))='completed'),
    'files_uploaded', (select count(*) from public.files f where f.clinic_id=v_clinic_id and f.archived_at is null and timezone('Asia/Kolkata',f.created_at)::date between v_from and v_to),
    'xrays_uploaded', (select count(*) from public.files f where f.clinic_id=v_clinic_id and f.archived_at is null and lower(coalesce(f.file_type,''))='xray' and timezone('Asia/Kolkata',f.created_at)::date between v_from and v_to),
    'net_collections', coalesce((select sum(case when lower(coalesce(py.status,'active'))='active' then py.amount when lower(coalesce(py.status,''))='refund' then py.amount else 0 end) from public.payments py where py.clinic_id=v_clinic_id and timezone('Asia/Kolkata',py.created_at)::date between v_from and v_to),0),
    'active_payment_count', (select count(*) from public.payments py where py.clinic_id=v_clinic_id and lower(coalesce(py.status,'active'))='active' and timezone('Asia/Kolkata',py.created_at)::date between v_from and v_to),
    'refund_total', coalesce((select sum(abs(py.amount)) from public.payments py where py.clinic_id=v_clinic_id and lower(coalesce(py.status,''))='refund' and timezone('Asia/Kolkata',py.created_at)::date between v_from and v_to),0),
    'billed_amount', coalesce((select sum(inv.total_amount) from public.invoices inv where inv.clinic_id=v_clinic_id and timezone('Asia/Kolkata',inv.created_at)::date between v_from and v_to),0),
    'outstanding_due_now', coalesce((select sum(inv.due_amount) from public.invoices inv where inv.clinic_id=v_clinic_id and inv.due_amount>0 and lower(coalesce(inv.status,'')) in ('unpaid','partial')),0),
    'financial_adjustments', (select count(*) from public.financial_adjustments fa where fa.clinic_id=v_clinic_id and timezone('Asia/Kolkata',fa.created_at)::date between v_from and v_to)
  ) into v_result;

  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_capdent_ai_patient_history(p_patient_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_clinic_id uuid;
  v_role text;
  v_patient_exists boolean := false;
  v_visits jsonb := '[]'::jsonb;
  v_treatments jsonb := '[]'::jsonb;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select p.clinic_id, lower(coalesce(p.role, ''))
    into v_clinic_id, v_role
  from public.profiles p
  where p.id = v_user_id
    and p.active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Active clinic not found for current user';
  end if;

  if v_role not in ('owner', 'head_doctor', 'working_doctor', 'doctor') then
    raise exception 'Clinical AI summary requires doctor access';
  end if;

  select exists(
    select 1
    from public.patients p
    where p.id = p_patient_id
      and p.clinic_id = v_clinic_id
      and p.archived_at is null
  ) into v_patient_exists;

  if not v_patient_exists then
    raise exception 'Patient not found in current clinic';
  end if;

  select coalesce(jsonb_agg(row_to_json(v)::jsonb order by v.visit_date desc), '[]'::jsonb)
  into v_visits
  from (
    select
      pv.id,
      pv.visit_date,
      left(coalesce(pv.chief_complaint, ''), 240) as chief_complaint,
      left(coalesce(pv.diagnosis, ''), 320) as diagnosis,
      pv.visit_status,
      pv.next_appointment_date
    from public.patient_visits pv
    where pv.patient_id = p_patient_id
      and pv.clinic_id = v_clinic_id
    order by pv.visit_date desc
    limit 12
  ) v;

  select coalesce(jsonb_agg(row_to_json(t)::jsonb order by t.created_at desc), '[]'::jsonb)
  into v_treatments
  from (
    select
      tr.visit_id,
      tr.created_at,
      left(coalesce(tr.treatment_name, ''), 180) as treatment_name,
      left(coalesce(tr.category, ''), 120) as category,
      left(coalesce(tr.status, ''), 80) as status
    from public.treatments tr
    where tr.patient_id = p_patient_id
      and tr.clinic_id = v_clinic_id
    order by tr.created_at desc
    limit 30
  ) t;

  return jsonb_build_object(
    'patient_id', p_patient_id,
    'user_role', v_role,
    'visit_count_included', jsonb_array_length(v_visits),
    'treatment_count_included', jsonb_array_length(v_treatments),
    'visits', v_visits,
    'treatments', v_treatments,
    'privacy', jsonb_build_object(
      'identifiers_included', false,
      'doctor_notes_included', false,
      'medical_history_included', false,
      'files_included', false,
      'max_visits', 12,
      'max_treatments', 30
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_capdent_ai_period_analytics(p_period text DEFAULT 'weekly'::text)
 RETURNS TABLE(clinic_name text, currency_code text, user_role text, can_view_finance boolean, period_key text, period_start date, period_end date, previous_start date, previous_end date, patients_count integer, previous_patients_count integer, new_patients_count integer, previous_new_patients_count integer, appointments_count integer, previous_appointments_count integer, completed_count integer, previous_completed_count integer, visits_count integer, previous_visits_count integer, treatments_count integer, previous_treatments_count integer, gallery_uploads_count integer, previous_gallery_uploads_count integer, net_collections numeric, previous_net_collections numeric, outstanding_dues_now numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_clinic_id uuid;
  v_role text;
  v_can_view_finance boolean := false;
  v_period text := lower(coalesce(nullif(trim(p_period), ''), 'weekly'));
  v_today date := timezone('Asia/Kolkata', now())::date;
  v_start date;
  v_end date;
  v_prev_start date;
  v_prev_end date;
  v_elapsed integer;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select p.clinic_id, lower(coalesce(p.role, ''))
  into v_clinic_id, v_role
  from public.profiles p
  where p.id = v_user_id
    and p.active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Active clinic not found for current user';
  end if;

  v_can_view_finance := v_role in ('owner', 'head_doctor', 'receptionist');

  case v_period
    when 'daily' then
      v_start := v_today;
      v_end := v_today;
      v_prev_start := v_today - 1;
      v_prev_end := v_today - 1;
    when 'tomorrow' then
      v_start := v_today + 1;
      v_end := v_today + 1;
      v_prev_start := v_today;
      v_prev_end := v_today;
    when 'weekly' then
      v_start := date_trunc('week', v_today::timestamp)::date;
      v_end := v_today;
      v_elapsed := v_end - v_start;
      v_prev_start := v_start - 7;
      v_prev_end := v_prev_start + v_elapsed;
    when 'monthly' then
      v_start := date_trunc('month', v_today::timestamp)::date;
      v_end := v_today;
      v_elapsed := v_end - v_start;
      v_prev_start := (v_start - interval '1 month')::date;
      v_prev_end := least(v_prev_start + v_elapsed, v_start - 1);
    else
      raise exception 'Unsupported period. Use daily, tomorrow, weekly, or monthly.';
  end case;

  return query
  select
    c.name::text,
    coalesce(c.currency_code, 'INR')::text,
    v_role::text,
    v_can_view_finance,
    v_period::text,
    v_start,
    v_end,
    v_prev_start,
    v_prev_end,
    coalesce((select count(distinct q.patient_id)::integer from (
      select a.patient_id from public.appointments a where a.clinic_id = v_clinic_id and timezone('Asia/Kolkata', a.appointment_time)::date between v_start and v_end and lower(coalesce(a.status, '')) not in ('cancelled','canceled','no_show')
      union
      select pv.patient_id from public.patient_visits pv where pv.clinic_id = v_clinic_id and timezone('Asia/Kolkata', pv.visit_date)::date between v_start and v_end
      union
      select p.id from public.patients p where p.clinic_id = v_clinic_id and p.archived_at is null and timezone('Asia/Kolkata', p.created_at)::date between v_start and v_end
    ) q),0),
    coalesce((select count(distinct q.patient_id)::integer from (
      select a.patient_id from public.appointments a where a.clinic_id = v_clinic_id and timezone('Asia/Kolkata', a.appointment_time)::date between v_prev_start and v_prev_end and lower(coalesce(a.status, '')) not in ('cancelled','canceled','no_show')
      union
      select pv.patient_id from public.patient_visits pv where pv.clinic_id = v_clinic_id and timezone('Asia/Kolkata', pv.visit_date)::date between v_prev_start and v_prev_end
      union
      select p.id from public.patients p where p.clinic_id = v_clinic_id and p.archived_at is null and timezone('Asia/Kolkata', p.created_at)::date between v_prev_start and v_prev_end
    ) q),0),
    coalesce((select count(*)::integer from public.patients p where p.clinic_id = v_clinic_id and p.archived_at is null and timezone('Asia/Kolkata', p.created_at)::date between v_start and v_end),0),
    coalesce((select count(*)::integer from public.patients p where p.clinic_id = v_clinic_id and p.archived_at is null and timezone('Asia/Kolkata', p.created_at)::date between v_prev_start and v_prev_end),0),
    coalesce((select count(*)::integer from public.appointments a where a.clinic_id = v_clinic_id and timezone('Asia/Kolkata', a.appointment_time)::date between v_start and v_end and lower(coalesce(a.status, '')) not in ('cancelled','canceled','no_show')),0),
    coalesce((select count(*)::integer from public.appointments a where a.clinic_id = v_clinic_id and timezone('Asia/Kolkata', a.appointment_time)::date between v_prev_start and v_prev_end and lower(coalesce(a.status, '')) not in ('cancelled','canceled','no_show')),0),
    coalesce((select count(*)::integer from public.appointments a where a.clinic_id = v_clinic_id and timezone('Asia/Kolkata', a.appointment_time)::date between v_start and v_end and lower(coalesce(a.status, '')) in ('completed','done')),0),
    coalesce((select count(*)::integer from public.appointments a where a.clinic_id = v_clinic_id and timezone('Asia/Kolkata', a.appointment_time)::date between v_prev_start and v_prev_end and lower(coalesce(a.status, '')) in ('completed','done')),0),
    coalesce((select count(*)::integer from public.patient_visits pv where pv.clinic_id = v_clinic_id and timezone('Asia/Kolkata', pv.visit_date)::date between v_start and v_end),0),
    coalesce((select count(*)::integer from public.patient_visits pv where pv.clinic_id = v_clinic_id and timezone('Asia/Kolkata', pv.visit_date)::date between v_prev_start and v_prev_end),0),
    coalesce((select count(*)::integer from public.treatments t where t.clinic_id = v_clinic_id and timezone('Asia/Kolkata', t.created_at)::date between v_start and v_end),0),
    coalesce((select count(*)::integer from public.treatments t where t.clinic_id = v_clinic_id and timezone('Asia/Kolkata', t.created_at)::date between v_prev_start and v_prev_end),0),
    coalesce((select count(*)::integer from public.files f where f.clinic_id = v_clinic_id and f.archived_at is null and timezone('Asia/Kolkata', f.created_at)::date between v_start and v_end),0),
    coalesce((select count(*)::integer from public.files f where f.clinic_id = v_clinic_id and f.archived_at is null and timezone('Asia/Kolkata', f.created_at)::date between v_prev_start and v_prev_end),0),
    case when v_can_view_finance then coalesce((select sum(py.amount)::numeric from public.payments py where py.clinic_id = v_clinic_id and coalesce(lower(py.status),'active') in ('active','corrected','refund') and timezone('Asia/Kolkata', py.created_at)::date between v_start and v_end),0) else null end,
    case when v_can_view_finance then coalesce((select sum(py.amount)::numeric from public.payments py where py.clinic_id = v_clinic_id and coalesce(lower(py.status),'active') in ('active','corrected','refund') and timezone('Asia/Kolkata', py.created_at)::date between v_prev_start and v_prev_end),0) else null end,
    case when v_can_view_finance then coalesce((select sum(inv.due_amount)::numeric from public.invoices inv where inv.clinic_id = v_clinic_id and inv.due_amount > 0 and lower(coalesce(inv.status,'')) in ('unpaid','partial')),0) else null end
  from public.clinics c
  where c.id = v_clinic_id
  limit 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_capdent_entitlements_v2()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_clinic_id uuid;
  v_subscription public.clinic_subscriptions%rowtype;
  v_plan public.capdent_plan_catalog%rowtype;
  v_settings public.clinic_pricing_settings%rowtype;
  v_legacy_plan text := 'free';
  v_plan_code text := 'free';
  v_patient_count integer := 0;
  v_storage_used_bytes bigint := 0;
  v_pricing_visible boolean := false;
  v_shadow_mode boolean := false;
  v_global_enforcement boolean := false;
  v_intelligence_released boolean := false;
  v_multi_clinic_released boolean := false;
  v_effective_enforcement boolean := false;
  v_can_add_patient boolean := true;
  v_would_block boolean := false;
  v_remaining integer;
  v_analytics_enabled boolean := false;
  v_multi_clinic_enabled boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Login required';
  end if;

  v_clinic_id := public.current_clinic_id();
  if v_clinic_id is null then
    raise exception 'Clinic profile not found';
  end if;

  select count(*)::integer
  into v_patient_count
  from public.patients p
  where p.clinic_id = v_clinic_id;

  select *
  into v_subscription
  from public.clinic_subscriptions cs
  where cs.clinic_id = v_clinic_id
  limit 1;

  if found then
    v_legacy_plan := lower(coalesce(v_subscription.plan_name, 'free'));

    if lower(coalesce(v_subscription.status, 'free')) in ('active', 'grace_period')
       and lower(coalesce(v_subscription.google_play_status, 'not_started'))
         not in ('cancelled', 'expired', 'account_hold') then
      v_plan_code := case
        when v_legacy_plan in ('clinic_intelligence', 'intelligence') then 'intelligence'
        when v_legacy_plan in ('professional', 'google_play_monthly', 'cloud') then 'cloud'
        else 'free'
      end;
    end if;
  end if;

  select *
  into v_plan
  from public.capdent_plan_catalog pc
  where pc.code = v_plan_code
    and pc.active = true
  limit 1;

  if not found then
    select *
    into v_plan
    from public.capdent_plan_catalog pc
    where pc.code = 'free'
    limit 1;
    v_plan_code := 'free';
  end if;

  select *
  into v_settings
  from public.clinic_pricing_settings cps
  where cps.clinic_id = v_clinic_id
  limit 1;

  select coalesce((select enabled from public.capdent_pricing_flags where key = 'pricing_v2_visible'), false)
  into v_pricing_visible;

  select coalesce((select enabled from public.capdent_pricing_flags where key = 'patient_limit_shadow_mode'), false)
  into v_shadow_mode;

  select coalesce((select enabled from public.capdent_pricing_flags where key = 'patient_limit_enforcement'), false)
  into v_global_enforcement;

  select coalesce((select enabled from public.capdent_pricing_flags where key = 'intelligence_enabled'), false)
  into v_intelligence_released;

  select coalesce((select enabled from public.capdent_pricing_flags where key = 'multi_clinic_enabled'), false)
  into v_multi_clinic_released;

  -- Three independent conditions are required. Existing/missing clinic settings
  -- fail open because grandfathered defaults to true here.
  v_effective_enforcement :=
    v_global_enforcement
    and coalesce(v_settings.patient_limit_enforced, false)
    and not coalesce(v_settings.grandfathered, true);

  if v_plan.patient_limit is null then
    v_remaining := null;
    v_would_block := false;
  else
    v_remaining := greatest(v_plan.patient_limit - v_patient_count, 0);
    v_would_block := v_patient_count >= v_plan.patient_limit;
  end if;

  -- This read-only function reports whether a future server mutation would be
  -- allowed. It does not perform or reject any patient insert itself.
  v_can_add_patient := not v_effective_enforcement or not v_would_block;

  v_analytics_enabled :=
    v_plan.analytics_enabled
    and v_intelligence_released
    and coalesce(v_settings.intelligence_enabled_override, true);

  v_multi_clinic_enabled :=
    v_plan.multi_clinic_enabled
    and v_multi_clinic_released
    and coalesce(v_settings.multi_clinic_enabled_override, true);

  -- Supabase Storage objects currently use clinic_id as the first path segment.
  -- Older/non-matching objects are ignored rather than affecting access.
  select coalesce(
    sum(
      case
        when so.metadata is not null
          and so.metadata ? 'size'
          and (so.metadata ->> 'size') ~ '^[0-9]+$'
        then (so.metadata ->> 'size')::bigint
        else 0
      end
    ),
    0
  )
  into v_storage_used_bytes
  from storage.objects so
  where split_part(so.name, '/', 1) = v_clinic_id::text;

  return jsonb_build_object(
    'version', 2,
    'clinicId', v_clinic_id,
    'legacyPlanName', v_legacy_plan,
    'plan', v_plan_code,
    'planLabel', v_plan.display_name,
    'monthlyPrice', v_plan.monthly_price,
    'patientCount', v_patient_count,
    'patientLimit', v_plan.patient_limit,
    'remainingPatients', v_remaining,
    'canAddPatient', v_can_add_patient,
    'wouldBlockAtCurrentCount', v_would_block,
    'patientLimitEnforced', v_effective_enforcement,
    'shadowMode', v_shadow_mode,
    'pricingVisible', v_pricing_visible,
    'storageUsedBytes', v_storage_used_bytes,
    'storageLimitBytes', v_plan.storage_limit_bytes,
    'analyticsEnabled', v_analytics_enabled,
    'multiClinicEnabled', v_multi_clinic_enabled,
    'clinicLimit', v_plan.clinic_limit,
    'grandfathered', coalesce(v_settings.grandfathered, true),
    'pricingPolicyVersion', coalesce(v_settings.pricing_policy_version, 1),
    'subscriptionStatus', coalesce(v_subscription.status, 'free'),
    'currentPeriodEnd', v_subscription.current_period_end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.invoke_capdent_google_play_subscription_sync()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_secret text;
  v_request_id bigint;
begin
  select secret.decrypted_secret
  into v_secret
  from vault.decrypted_secrets secret
  where secret.name = 'capdent_google_play_sync_secret'
  limit 1;

  if v_secret is null or char_length(v_secret) < 32 then
    raise warning 'CapDent Google Play sync ignored: Vault secret is unavailable';
    return null;
  end if;

  select net.http_post(
    url := 'https://mzjtdcpbvoximdukpukd.supabase.co/functions/v1/sync-google-play-subscriptions',
    body := jsonb_build_object('mode', 'maintenance'),
    headers := jsonb_build_object(
      'Content-Type',
      'application/json',
      'x-capdent-google-play-sync-secret',
      v_secret
    ),
    timeout_milliseconds := 15000
  )
  into v_request_id;

  return v_request_id;
exception
  when others then
    raise warning 'CapDent Google Play lifecycle sync invocation failed: %',
      sqlerrm;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.invoke_capdent_payment_notification(p_job_id uuid DEFAULT NULL::uuid, p_mode text DEFAULT 'dispatch'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_secret text;
  v_request_id bigint;
  v_body jsonb;
begin
  if p_mode not in ('dispatch', 'maintenance', 'receipts') then
    raise warning 'CapDent payment notification invocation ignored: invalid mode';
    return null;
  end if;

  if p_mode = 'dispatch' and p_job_id is null then
    raise warning 'CapDent payment notification invocation ignored: missing job id';
    return null;
  end if;

  select secret.decrypted_secret
  into v_secret
  from vault.decrypted_secrets secret
  where secret.name = 'capdent_payment_notification_webhook_secret'
  limit 1;

  if v_secret is null or char_length(v_secret) < 32 then
    raise warning 'CapDent payment notification invocation ignored: Vault secret is unavailable';
    return null;
  end if;

  v_body := case
    when p_mode = 'dispatch' then jsonb_build_object('job_id', p_job_id)
    else jsonb_build_object('mode', p_mode)
  end;

  select net.http_post(
    url := 'https://mzjtdcpbvoximdukpukd.supabase.co/functions/v1/send-payment-notification',
    body := v_body,
    headers := jsonb_build_object(
      'Content-Type',
      'application/json',
      'x-capdent-webhook-secret',
      v_secret
    ),
    timeout_milliseconds := 5000
  )
  into v_request_id;

  return v_request_id;
exception
  when others then
    raise warning 'CapDent payment notification invocation failed: %', sqlerrm;
    return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_patient_visit_completed(p_patient_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_count integer;
begin
  select pr.clinic_id
  into v_clinic_id
  from public.profiles pr
  where pr.id = auth.uid()
    and pr.active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Clinic not found for current user';
  end if;

  update public.appointments ap
  set status = 'completed'
  where ap.clinic_id = v_clinic_id
    and ap.patient_id = p_patient_id
    and timezone('Asia/Kolkata', ap.appointment_time)::date = timezone('Asia/Kolkata', now())::date
    and lower(coalesce(ap.status, '')) in ('waiting', 'checked_in', 'scheduled', 'booked');

  get diagnostics v_count = row_count;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.owner_update_staff_access(p_staff_id uuid, p_staff_role text DEFAULT NULL::text, p_staff_active boolean DEFAULT NULL::boolean)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  actor public.profiles;
  updated_profile public.profiles;
  normalized_role text;
begin
  if auth.uid() is null then
    raise exception 'Login required';
  end if;

  select * into actor
  from public.profiles
  where id = auth.uid()
    and active = true;

  if actor.id is null or actor.clinic_id is null then
    raise exception 'Active clinic profile not found';
  end if;

  if actor.role not in ('owner', 'head_doctor') then
    raise exception 'Only clinic owner can manage staff access';
  end if;

  if p_staff_id = auth.uid() then
    raise exception 'You cannot change your own owner access';
  end if;

  if p_staff_role is not null then
    normalized_role := case
      when p_staff_role = 'doctor' then 'working_doctor'
      else p_staff_role
    end;

    if normalized_role not in ('working_doctor', 'receptionist') then
      raise exception 'Invalid staff role';
    end if;
  end if;

  update public.profiles
  set
    role = coalesce(normalized_role, role),
    active = coalesce(p_staff_active, active)
  where id = p_staff_id
    and clinic_id = actor.clinic_id
    and role not in ('owner', 'head_doctor')
  returning * into updated_profile;

  if updated_profile.id is null then
    raise exception 'Staff member not found or owner access cannot be changed';
  end if;

  return updated_profile;
end;
$function$

