CREATE OR REPLACE FUNCTION public.protect_profile_access_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_actor_clinic_id uuid;
  v_actor_active boolean;
begin
  if v_actor_id is null then
    return new;
  end if;

  select role, clinic_id, active
  into v_actor_role, v_actor_clinic_id, v_actor_active
  from public.profiles
  where id = v_actor_id;

  if not coalesce(v_actor_active, false) then
    raise exception 'Active clinic profile required.' using errcode = '42501';
  end if;

  if new.id is distinct from old.id
     or new.clinic_id is distinct from old.clinic_id
     or new.created_at is distinct from old.created_at
     or new.invite_code is distinct from old.invite_code then
    raise exception 'Profile identity and clinic assignment cannot be changed.' using errcode = '42501';
  end if;

  if old.id = v_actor_id then
    if new.role is distinct from old.role
       or new.active is distinct from old.active
       or new.email is distinct from old.email then
      raise exception 'You cannot change your own role, access status or login email.' using errcode = '42501';
    end if;
    return new;
  end if;

  if v_actor_role not in ('owner','head_doctor')
     or old.clinic_id is distinct from v_actor_clinic_id then
    raise exception 'Only clinic administrators can update staff profiles.' using errcode = '42501';
  end if;

  if old.role = 'owner' then
    raise exception 'Clinic owner access cannot be modified.' using errcode = '42501';
  end if;

  if new.email is distinct from old.email then
    raise exception 'Staff login email must be changed through the authentication workflow.' using errcode = '42501';
  end if;

  if new.role = 'owner' then
    raise exception 'The owner role cannot be assigned through staff management.' using errcode = '42501';
  end if;

  if v_actor_role = 'head_doctor'
     and (old.role = 'head_doctor' or new.role = 'head_doctor') then
    raise exception 'Only the clinic owner can manage head-doctor access.' using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_invoice_financials(p_invoice_id uuid)
 RETURNS invoices
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invoice public.invoices;
  v_paid numeric;
begin
  select * into v_invoice
  from public.invoices
  where id = p_invoice_id
  for update;

  if not found then
    raise exception 'Invoice not found.' using errcode = 'P0002';
  end if;

  select coalesce(sum(p.amount), 0)
  into v_paid
  from public.payments p
  where p.invoice_id = p_invoice_id
    and p.status in ('active', 'corrected', 'refund');

  if v_paid < 0 then
    raise exception 'Refunds cannot exceed payments received.' using errcode = '22023';
  end if;

  if v_paid > v_invoice.total_amount + 0.01 then
    raise exception 'Effective payments cannot exceed the current invoice total.' using errcode = '22023';
  end if;

  update public.invoices
  set
    paid_amount = v_paid,
    due_amount = greatest(total_amount - v_paid, 0),
    status = public.invoice_status(total_amount, v_paid),
    updated_at = now(),
    updated_by = auth.uid()
  where id = p_invoice_id
  returning * into v_invoice;

  return v_invoice;
end;
$function$

CREATE OR REPLACE FUNCTION public.reception_quick_checkin(p_patient_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_age integer DEFAULT NULL::integer, p_gender text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_op_amount numeric DEFAULT 300, p_payment_method text DEFAULT 'Cash'::text, p_op_status text DEFAULT 'paid'::text, p_waiver_reason text DEFAULT NULL::text)
 RETURNS TABLE(patient_id uuid, appointment_id uuid, invoice_id uuid, payment_id uuid, op_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_clinic_id uuid;
  v_patient_id uuid;
  v_patient_clinic_id uuid;
  v_appointment_id uuid;
  v_invoice_id uuid;
  v_payment_id uuid;
  v_amount numeric;
  v_patient_code text;
  v_op_status text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  select pr.clinic_id
  into v_clinic_id
  from public.profiles pr
  where pr.id = v_user_id
    and pr.active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Clinic not found for current user';
  end if;

  v_op_status := lower(trim(coalesce(p_op_status, 'paid')));
  if v_op_status not in ('paid', 'pending', 'waived') then
    v_op_status := 'paid';
  end if;

  v_amount := coalesce(p_op_amount, 300);
  if v_op_status in ('paid', 'pending') and v_amount <= 0 then
    raise exception 'OP fee must be greater than zero';
  end if;
  if v_op_status = 'waived' then
    v_amount := 0;
  end if;

  if p_patient_id is null then
    if coalesce(trim(p_name), '') = '' then
      raise exception 'Patient name is required';
    end if;

    v_patient_code := 'P-' || to_char(now(), 'YYMMDD') || '-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 5));

    insert into public.patients (clinic_id, patient_code, name, phone, age, gender, address)
    values (
      v_clinic_id,
      v_patient_code,
      trim(p_name),
      nullif(trim(coalesce(p_phone, '')), ''),
      p_age,
      nullif(trim(coalesce(p_gender, '')), ''),
      nullif(trim(coalesce(p_address, '')), '')
    )
    returning id into v_patient_id;
  else
    select pt.clinic_id
    into v_patient_clinic_id
    from public.patients pt
    where pt.id = p_patient_id
    limit 1;

    if v_patient_clinic_id is null then
      raise exception 'Patient not found';
    end if;

    if v_patient_clinic_id <> v_clinic_id then
      raise exception 'Patient does not belong to your clinic';
    end if;

    v_patient_id := p_patient_id;
  end if;

  if v_op_status = 'paid' then
    insert into public.invoices (
      clinic_id, patient_id, total_amount, paid_amount, due_amount,
      status, invoice_type, payment_category, notes
    )
    values (
      v_clinic_id, v_patient_id, v_amount, v_amount, 0,
      'paid', 'op_fee', 'op_fee', 'OP fee collected during quick check-in'
    )
    returning id into v_invoice_id;

    insert into public.payments (
      clinic_id, patient_id, invoice_id, amount, payment_method,
      notes, payment_category, collected_by
    )
    values (
      v_clinic_id, v_patient_id, v_invoice_id, v_amount,
      coalesce(nullif(trim(p_payment_method), ''), 'Cash'),
      'OP fee - patient checked in', 'op_fee', v_user_id
    )
    returning id into v_payment_id;

  elsif v_op_status = 'pending' then
    insert into public.invoices (
      clinic_id, patient_id, total_amount, paid_amount, due_amount,
      status, invoice_type, payment_category, notes
    )
    values (
      v_clinic_id, v_patient_id, v_amount, 0, v_amount,
      'unpaid', 'op_fee', 'op_fee', 'OP fee pending during quick check-in'
    )
    returning id into v_invoice_id;

    v_payment_id := null;
  else
    v_invoice_id := null;
    v_payment_id := null;
  end if;

  -- doctor_id intentionally stays null. Doctor is saved in patient_visits.doctor_id when visit is added.
  insert into public.appointments (
    clinic_id, patient_id, doctor_id, appointment_time, status,
    notes, op_fee_amount, op_fee_status, op_fee_waiver_reason,
    op_fee_waived_by, op_fee_waived_at
  )
  values (
    v_clinic_id, v_patient_id, null, now(), 'scheduled',
    case
      when v_op_status = 'paid' then 'Walk-in / OP fee collected / waiting'
      when v_op_status = 'pending' then 'Walk-in / OP fee pending / waiting'
      when v_op_status = 'waived' then 'Walk-in / OP fee waived / waiting'
      else 'Walk-in / waiting'
    end,
    v_amount,
    v_op_status,
    case when v_op_status = 'waived' then nullif(trim(coalesce(p_waiver_reason, '')), '') else null end,
    case when v_op_status = 'waived' then v_user_id else null end,
    case when v_op_status = 'waived' then now() else null end
  )
  returning id into v_appointment_id;

  return query
  select v_patient_id, v_appointment_id, v_invoice_id, v_payment_id, v_amount;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_admin_client_error(p_release text, p_route text, p_message text, p_stack text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb, p_user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_clinic_id uuid;
  v_error_id uuid;
  v_context jsonb;
begin
  if not public.current_user_is_owner() then
    raise exception 'Clinic Admin error reporting is available only to owners and head doctors.' using errcode = '42501';
  end if;

  v_clinic_id := public.current_user_clinic_id();
  if v_clinic_id is null then
    raise exception 'No active clinic is linked to this account.' using errcode = '42501';
  end if;

  if (
    select count(*)
    from public.admin_client_error_logs
    where user_id = auth.uid()
      and created_at >= now() - interval '10 minutes'
  ) >= 30 then
    return null;
  end if;

  v_context := case
    when p_context is null then '{}'::jsonb
    when length(p_context::text) > 4000 then jsonb_build_object('truncated', true)
    else p_context
  end;

  insert into public.admin_client_error_logs (
    clinic_id,
    user_id,
    release,
    route,
    message,
    stack,
    context,
    user_agent
  ) values (
    v_clinic_id,
    auth.uid(),
    left(coalesce(nullif(trim(p_release), ''), 'unknown'), 80),
    left(coalesce(nullif(trim(p_route), ''), '/portal/'), 300),
    left(coalesce(nullif(trim(p_message), ''), 'Unknown Clinic Admin client error'), 1000),
    nullif(left(coalesce(p_stack, ''), 4000), ''),
    v_context,
    nullif(left(coalesce(p_user_agent, ''), 500), '')
  )
  returning id into v_error_id;

  return v_error_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_patient_payment(p_patient_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'Cash'::text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(payment_id uuid, invoice_id uuid, applied_amount numeric, remaining_due numeric, invoice_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid;
  v_clinic_id uuid;
  v_patient_clinic_id uuid;
  v_remaining numeric;
  v_apply numeric;
  v_payment_id uuid;
  v_invoice record;
  v_new_paid numeric;
  v_new_due numeric;
  v_new_status text;
  v_had_invoice boolean := false;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  if coalesce(p_amount, 0) <= 0 then
    raise exception 'Payment amount must be greater than zero';
  end if;

  select clinic_id
  into v_clinic_id
  from public.profiles
  where id = v_user_id
    and active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Clinic not found for current user';
  end if;

  select clinic_id
  into v_patient_clinic_id
  from public.patients
  where id = p_patient_id
  limit 1;

  if v_patient_clinic_id is null then
    raise exception 'Patient not found';
  end if;

  if v_patient_clinic_id <> v_clinic_id then
    raise exception 'Patient does not belong to your clinic';
  end if;

  v_remaining := p_amount;

  if p_invoice_id is not null then
    select *
    into v_invoice
    from public.invoices
    where id = p_invoice_id
      and patient_id = p_patient_id
      and clinic_id = v_clinic_id
    for update;

    if not found then
      raise exception 'Invoice not found';
    end if;

    if greatest(coalesce(v_invoice.due_amount, 0), 0) <= 0 then
      raise exception 'This invoice is already paid';
    end if;

    v_apply := least(v_remaining, greatest(coalesce(v_invoice.due_amount, 0), 0));
    v_new_paid := coalesce(v_invoice.paid_amount, 0) + v_apply;
    v_new_due := greatest(coalesce(v_invoice.total_amount, 0) - v_new_paid, 0);
    v_new_status :=
      case
        when v_new_due <= 0 then 'paid'
        when v_new_paid > 0 then 'partial'
        else 'unpaid'
      end;

    update public.invoices
    set paid_amount = v_new_paid, due_amount = v_new_due, status = v_new_status
    where id = v_invoice.id;

    insert into public.payments (clinic_id, patient_id, invoice_id, amount, payment_method, notes)
    values (
      v_clinic_id,
      p_patient_id,
      v_invoice.id,
      v_apply,
      nullif(trim(coalesce(p_payment_method, 'Cash')), ''),
      coalesce(nullif(trim(coalesce(p_notes, '')), ''), 'Pending amount collected')
    )
    returning id into v_payment_id;

    return query select v_payment_id, v_invoice.id, v_apply, v_new_due, v_new_status;
    return;
  end if;

  for v_invoice in
    select *
    from public.invoices
    where patient_id = p_patient_id
      and clinic_id = v_clinic_id
      and greatest(coalesce(due_amount, 0), 0) > 0
    order by created_at asc
    for update
  loop
    v_had_invoice := true;
    exit when v_remaining <= 0;

    v_apply := least(v_remaining, greatest(coalesce(v_invoice.due_amount, 0), 0));
    v_new_paid := coalesce(v_invoice.paid_amount, 0) + v_apply;
    v_new_due := greatest(coalesce(v_invoice.total_amount, 0) - v_new_paid, 0);
    v_new_status :=
      case
        when v_new_due <= 0 then 'paid'
        when v_new_paid > 0 then 'partial'
        else 'unpaid'
      end;

    update public.invoices
    set paid_amount = v_new_paid, due_amount = v_new_due, status = v_new_status
    where id = v_invoice.id;

    insert into public.payments (clinic_id, patient_id, invoice_id, amount, payment_method, notes)
    values (
      v_clinic_id,
      p_patient_id,
      v_invoice.id,
      v_apply,
      nullif(trim(coalesce(p_payment_method, 'Cash')), ''),
      coalesce(nullif(trim(coalesce(p_notes, '')), ''), 'Pending amount collected')
    )
    returning id into v_payment_id;

    v_remaining := v_remaining - v_apply;

    return query select v_payment_id, v_invoice.id, v_apply, v_new_due, v_new_status;
  end loop;

  if not v_had_invoice then
    raise exception 'No pending invoices found for this patient';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_patient_payment(p_patient_id uuid, p_invoice_id uuid DEFAULT NULL::uuid, p_amount numeric DEFAULT 0, p_payment_method text DEFAULT 'Cash'::text, p_notes text DEFAULT NULL::text, p_payment_category text DEFAULT 'pending_collection'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  caller public.profiles;
  remaining numeric := coalesce(p_amount, 0);
  invoice_row public.invoices;
  applied numeric;
begin
  select * into caller from public.profiles where id = auth.uid() and active = true limit 1;
  if caller.id is null or caller.clinic_id is null then
    raise exception 'Clinic profile not found';
  end if;

  if remaining <= 0 then
    raise exception 'Payment amount must be greater than zero';
  end if;

  if p_payment_category not in ('op_fee', 'xray_fee', 'medication_fee', 'treatment_fee', 'pending_collection', 'other') then
    raise exception 'Invalid payment category';
  end if;

  for invoice_row in
    select *
    from public.invoices
    where clinic_id = caller.clinic_id
      and patient_id = p_patient_id
      and due_amount > 0
      and (p_invoice_id is null or id = p_invoice_id)
    order by created_at asc
  loop
    exit when remaining <= 0;

    applied := least(remaining, invoice_row.due_amount);

    insert into public.payments (
      clinic_id, invoice_id, patient_id, amount, payment_method, notes, payment_category, collected_by
    )
    values (
      caller.clinic_id,
      invoice_row.id,
      p_patient_id,
      applied,
      p_payment_method,
      p_notes,
      case
        when p_payment_category = 'pending_collection'
          then coalesce(invoice_row.payment_category, 'pending_collection')
        else p_payment_category
      end,
      caller.id
    );

    update public.invoices
    set paid_amount = paid_amount + applied,
        due_amount = greatest(due_amount - applied, 0),
        status = public.invoice_status(total_amount, paid_amount + applied)
    where id = invoice_row.id;

    remaining := remaining - applied;
  end loop;

  if remaining > 0 then
    raise exception 'Payment amount exceeds pending balance';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_visit_with_tooth_chart(p_patient_id uuid, p_doctor_id uuid, p_chief_complaint text, p_doctor_notes text, p_next_appointment_date timestamp with time zone, p_followup_notes text, p_existing_treatment_id uuid, p_existing_treatment_status text, p_existing_payment_amount numeric, p_existing_payment_method text, p_treatments jsonb, p_chart_entries jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_clinic_id uuid;
  v_actor_role text;
  v_visit_id uuid := gen_random_uuid();
  v_appointment_id uuid;
  v_queue_count integer := 0;
  v_chart_count integer := 0;
  v_treatment_ids uuid[] := '{}'::uuid[];
  v_invoice_ids uuid[] := '{}'::uuid[];
  v_treatment jsonb;
  v_chart jsonb;
  v_treatment_id uuid;
  v_invoice_id uuid;
  v_treatment_name text;
  v_treatment_description text;
  v_treatment_category text;
  v_treatment_status text;
  v_cost numeric;
  v_paid numeric;
  v_due numeric;
  v_payment_method text;
  v_dentition text;
  v_tooth_code text;
  v_condition text;
  v_surfaces text[];
  v_chart_notes text;
  v_chart_treatment_name text;
  v_chart_treatment_status text;
  v_existing_invoice public.invoices%rowtype;
  v_remaining_existing_payment numeric;
  v_applied_existing_payment numeric;
begin
  if v_actor_id is null then
    raise exception 'Authentication required';
  end if;

  select p.clinic_id, p.role
  into v_clinic_id, v_actor_role
  from public.profiles p
  where p.id = v_actor_id
    and p.active = true
  limit 1;

  if v_clinic_id is null then
    raise exception 'Active clinic profile not found';
  end if;

  if v_actor_role not in (
    'owner',
    'head_doctor',
    'working_doctor',
    'doctor'
  ) then
    raise exception 'Only authorized dentists can save dental chart visits';
  end if;

  if not coalesce(
    (
      select c.tooth_chart_enabled
      from public.clinics c
      where c.id = v_clinic_id
    ),
    false
  ) then
    raise exception 'Dental chart is disabled for this clinic';
  end if;

  if not exists (
    select 1
    from public.patients patient
    where patient.id = p_patient_id
      and patient.clinic_id = v_clinic_id
  ) then
    raise exception 'Patient not found in the active clinic';
  end if;

  if not exists (
    select 1
    from public.profiles doctor
    where doctor.id = p_doctor_id
      and doctor.clinic_id = v_clinic_id
      and doctor.active = true
      and doctor.role in (
        'owner',
        'head_doctor',
        'working_doctor',
        'doctor'
      )
  ) then
    raise exception 'Treating doctor not found in the active clinic';
  end if;

  if nullif(trim(coalesce(p_chief_complaint, '')), '') is null then
    raise exception 'Chief complaint is required';
  end if;
  if char_length(p_chief_complaint) > 2000 then
    raise exception 'Chief complaint is too long';
  end if;
  if p_doctor_notes is not null and char_length(p_doctor_notes) > 4000 then
    raise exception 'Doctor notes are too long';
  end if;
  if p_followup_notes is not null and char_length(p_followup_notes) > 2000 then
    raise exception 'Follow-up notes are too long';
  end if;
  if p_next_appointment_date is not null
    and p_next_appointment_date <= now() then
    raise exception 'Follow-up appointment must be in the future';
  end if;

  if coalesce(jsonb_typeof(p_chart_entries), 'null') <> 'array'
    or jsonb_array_length(p_chart_entries) = 0
    or jsonb_array_length(p_chart_entries) > 52 then
    raise exception 'Dental chart entries must contain between 1 and 52 teeth';
  end if;

  if coalesce(jsonb_typeof(p_treatments), 'null') <> 'array'
    or jsonb_array_length(p_treatments) > 20 then
    raise exception 'Treatments must be a JSON array with no more than 20 rows';
  end if;

  if coalesce(p_existing_payment_amount, 0) < 0 then
    raise exception 'Existing treatment payment cannot be negative';
  end if;

  if p_existing_treatment_id is null then
    if coalesce(p_existing_payment_amount, 0) > 0
      or p_existing_treatment_status is not null then
      raise exception 'Existing treatment details require a treatment id';
    end if;
  else
    if p_existing_treatment_status not in (
      'planned',
      'ongoing',
      'completed'
    ) then
      raise exception 'An explicit valid existing treatment status is required';
    end if;

    if not exists (
      select 1
      from public.treatments treatment
      where treatment.id = p_existing_treatment_id
        and treatment.clinic_id = v_clinic_id
        and treatment.patient_id = p_patient_id
        and treatment.status in ('planned', 'ongoing', 'completed')
    ) then
      raise exception 'Existing treatment not found for this patient';
    end if;
  end if;

  insert into public.patient_visits (
    id,
    clinic_id,
    patient_id,
    doctor_id,
    visit_date,
    chief_complaint,
    diagnosis,
    doctor_notes,
    next_appointment_date,
    visit_status,
    created_by
  )
  values (
    v_visit_id,
    v_clinic_id,
    p_patient_id,
    p_doctor_id,
    now(),
    trim(p_chief_complaint),
    null,
    nullif(trim(coalesce(p_doctor_notes, '')), ''),
    p_next_appointment_date,
    'completed',
    v_actor_id
  );

  if p_existing_treatment_id is not null then
    update public.treatments
    set status = p_existing_treatment_status
    where id = p_existing_treatment_id
      and clinic_id = v_clinic_id
      and patient_id = p_patient_id;

    if coalesce(p_existing_payment_amount, 0) > 0 then
      v_remaining_existing_payment := p_existing_payment_amount;

      for v_existing_invoice in
        select invoice.*
        from public.invoices invoice
        where invoice.clinic_id = v_clinic_id
          and invoice.patient_id = p_patient_id
          and invoice.payment_category = 'treatment_fee'
          and invoice.due_amount > 0
        order by invoice.created_at, invoice.id
        for update
      loop
        exit when v_remaining_existing_payment <= 0;
        v_applied_existing_payment := least(
          v_remaining_existing_payment,
          v_existing_invoice.due_amount
        );

        update public.invoices
        set
          paid_amount = paid_amount + v_applied_existing_payment,
          due_amount = due_amount - v_applied_existing_payment,
          status = case
            when due_amount - v_applied_existing_payment <= 0 then 'paid'
            else 'partial'
          end
        where id = v_existing_invoice.id
          and clinic_id = v_clinic_id;

        insert into public.payments (
          clinic_id,
          invoice_id,
          patient_id,
          amount,
          payment_method,
          notes,
          payment_category,
          collected_by
        )
        values (
          v_clinic_id,
          v_existing_invoice.id,
          p_patient_id,
          v_applied_existing_payment,
          coalesce(nullif(trim(p_existing_payment_method), ''), 'Cash'),
          'Ongoing treatment payment',
          'treatment_fee',
          v_actor_id
        );

        v_remaining_existing_payment :=
          v_remaining_existing_payment - v_applied_existing_payment;
      end loop;

      if v_remaining_existing_payment > 0 then
        raise exception 'Existing payment exceeds pending treatment balance';
      end if;
    end if;
  end if;

  for v_treatment in
    select value
    from jsonb_array_elements(p_treatments)
  loop
    if jsonb_typeof(v_treatment) <> 'object' then
      raise exception 'Each treatment must be an object';
    end if;

    v_treatment_name := nullif(
      trim(coalesce(v_treatment->>'treatment_name', '')),
      ''
    );
    v_treatment_description := nullif(
      trim(coalesce(v_treatment->>'description', '')),
      ''
    );
    v_treatment_category := nullif(
      trim(coalesce(v_treatment->>'category', '')),
      ''
    );
    v_treatment_status := v_treatment->>'status';

    begin
      v_cost := coalesce((v_treatment->>'cost')::numeric, 0);
      v_paid := coalesce((v_treatment->>'paid_amount')::numeric, 0);
    exception
      when invalid_text_representation then
        raise exception 'Treatment cost and paid amount must be numeric';
    end;

    v_payment_method := coalesce(
      nullif(trim(v_treatment->>'payment_method'), ''),
      'Cash'
    );

    if v_treatment_name is null
      or char_length(v_treatment_name) > 160 then
      raise exception 'Treatment name is required and must be at most 160 characters';
    end if;
    if v_treatment_description is not null
      and char_length(v_treatment_description) > 2000 then
      raise exception 'Treatment description is too long';
    end if;
    if v_treatment_category is not null
      and char_length(v_treatment_category) > 120 then
      raise exception 'Treatment category is too long';
    end if;
    if v_treatment_status not in ('planned', 'ongoing', 'completed') then
      raise exception 'Every treatment requires an explicit valid status';
    end if;
    if v_cost < 0 or v_paid < 0 or v_paid > v_cost then
      raise exception 'Treatment amounts are invalid';
    end if;

    v_treatment_id := gen_random_uuid();
    insert into public.treatments (
      id,
      clinic_id,
      visit_id,
      patient_id,
      treatment_name,
      description,
      cost,
      status,
      category
    )
    values (
      v_treatment_id,
      v_clinic_id,
      v_visit_id,
      p_patient_id,
      v_treatment_name,
      v_treatment_description,
      v_cost,
      v_treatment_status,
      v_treatment_category
    );
    v_treatment_ids := array_append(v_treatment_ids, v_treatment_id);

    if v_cost > 0 then
      v_due := greatest(v_cost - v_paid, 0);
      v_invoice_id := gen_random_uuid();
      insert into public.invoices (
        id,
        clinic_id,
        patient_id,
        visit_id,
        total_amount,
        paid_amount,
        due_amount,
        status,
        invoice_type,
        payment_category,
        notes,
        created_by
      )
      values (
        v_invoice_id,
        v_clinic_id,
        p_patient_id,
        v_visit_id,
        v_cost,
        v_paid,
        v_due,
        case
          when v_due <= 0 then 'paid'
          when v_paid > 0 then 'partial'
          else 'unpaid'
        end,
        'treatment',
        'treatment_fee',
        v_treatment_name,
        v_actor_id
      );
      v_invoice_ids := array_append(v_invoice_ids, v_invoice_id);

      if v_paid > 0 then
        insert into public.payments (
          clinic_id,
          invoice_id,
          patient_id,
          amount,
          payment_method,
          notes,
          payment_category,
          collected_by
        )
        values (
          v_clinic_id,
          v_invoice_id,
          p_patient_id,
          v_paid,
          v_payment_method,
          'Invoice paid at charted visit creation',
          'treatment_fee',
          v_actor_id
        );
      end if;
    end if;
  end loop;

  for v_chart in
    select value
    from jsonb_array_elements(p_chart_entries)
  loop
    if jsonb_typeof(v_chart) <> 'object' then
      raise exception 'Each dental chart entry must be an object';
    end if;

    v_tooth_code := trim(coalesce(v_chart->>'tooth_code', ''));
    v_dentition := v_chart->>'dentition';
    v_condition := v_chart->>'condition';
    v_chart_notes := nullif(trim(coalesce(v_chart->>'notes', '')), '');
    v_chart_treatment_name := nullif(
      trim(coalesce(v_chart->>'treatment_name', '')),
      ''
    );
    v_chart_treatment_status := v_chart->>'treatment_status';

    if v_dentition not in ('permanent', 'primary') then
      raise exception 'Invalid dentition';
    end if;
    if not (
      (
        v_dentition = 'permanent'
        and v_tooth_code ~ '^[1-4][1-8]$'
      )
      or (
        v_dentition = 'primary'
        and v_tooth_code ~ '^[5-8][1-5]$'
      )
    ) then
      raise exception 'Invalid FDI tooth code % for % dentition',
        v_tooth_code,
        v_dentition;
    end if;
    if v_condition not in (
      'healthy',
      'caries',
      'filled',
      'missing',
      'crown',
      'root_canal',
      'implant',
      'extraction_planned',
      'unerupted'
    ) then
      raise exception 'Invalid dental condition for tooth %', v_tooth_code;
    end if;
    if v_chart_treatment_status not in (
      'planned',
      'ongoing',
      'completed'
    ) then
      raise exception 'Every chart entry requires an explicit treatment status';
    end if;
    if v_chart_notes is not null and char_length(v_chart_notes) > 1000 then
      raise exception 'Dental note is too long';
    end if;
    if v_chart_treatment_name is not null
      and char_length(v_chart_treatment_name) > 160 then
      raise exception 'Chart treatment name is too long';
    end if;
    if coalesce(jsonb_typeof(v_chart->'surfaces'), 'array') <> 'array' then
      raise exception 'Dental surfaces must be an array';
    end if;

    select coalesce(array_agg(distinct surface), '{}'::text[])
    into v_surfaces
    from jsonb_array_elements_text(
      coalesce(v_chart->'surfaces', '[]'::jsonb)
    ) as item(surface);

    if not (
      v_surfaces <@ array[
        'mesial',
        'distal',
        'occlusal',
        'buccal',
        'lingual'
      ]::text[]
    ) or cardinality(v_surfaces) > 5 then
      raise exception 'Invalid dental surface for tooth %', v_tooth_code;
    end if;

    insert into public.dental_chart_entries (
      clinic_id,
      patient_id,
      visit_id,
      recorded_by,
      tooth_code,
      dentition,
      condition,
      surfaces,
      notes,
      treatment_name,
      treatment_status
    )
    values (
      v_clinic_id,
      p_patient_id,
      v_visit_id,
      v_actor_id,
      v_tooth_code,
      v_dentition,
      v_condition,
      v_surfaces,
      v_chart_notes,
      v_chart_treatment_name,
      v_chart_treatment_status
    );
    v_chart_count := v_chart_count + 1;
  end loop;

  -- Complete only pre-existing same-day queue rows. This deliberately runs
  -- before inserting a same-day follow-up, so the new appointment cannot be
  -- marked completed accidentally.
  update public.appointments appointment
  set status = 'completed'
  where appointment.clinic_id = v_clinic_id
    and appointment.patient_id = p_patient_id
    and timezone('Asia/Kolkata', appointment.appointment_time)::date =
      timezone('Asia/Kolkata', now())::date
    and lower(coalesce(appointment.status, '')) in (
      'waiting',
      'checked_in',
      'scheduled',
      'booked'
    );
  get diagnostics v_queue_count = row_count;

  if p_next_appointment_date is not null then
    v_appointment_id := gen_random_uuid();
    insert into public.appointments (
      id,
      clinic_id,
      patient_id,
      doctor_id,
      appointment_time,
      status,
      notes,
      created_by
    )
    values (
      v_appointment_id,
      v_clinic_id,
      p_patient_id,
      p_doctor_id,
      p_next_appointment_date,
      'scheduled',
      nullif(trim(coalesce(p_followup_notes, '')), ''),
      v_actor_id
    );
  end if;

  return jsonb_build_object(
    'visit_id', v_visit_id,
    'treatment_ids', to_jsonb(v_treatment_ids),
    'invoice_ids', to_jsonb(v_invoice_ids),
    'appointment_id', v_appointment_id,
    'queue_rows_completed', v_queue_count,
    'chart_entries_created', v_chart_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_capdent_pricing_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_invoice_financial_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.original_total_amount := coalesce(new.original_total_amount, new.total_amount, 0);
  new.discount_amount := coalesce(new.discount_amount, 0);
  new.waived_amount := coalesce(new.waived_amount, 0);
  new.refunded_amount := coalesce(new.refunded_amount, 0);
  new.version_number := coalesce(new.version_number, 1);
  new.updated_at := coalesce(new.updated_at, now());
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_patient_visit_staff_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if new.created_by is null then
    new.created_by := v_user_id;
  end if;

  -- doctor_id must always be a real doctor/head doctor. Receptionists are only entry staff.
  if new.doctor_id is not null and not public.is_clinic_doctor(new.doctor_id, new.clinic_id) then
    if new.created_by is null then
      new.created_by := new.doctor_id;
    end if;
    new.doctor_id := null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_record_created_by_staff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    return new;
  end if;

  if tg_table_name = 'appointments' then
    if new.created_by is null then
      new.created_by := v_user_id;
    end if;
  elsif tg_table_name = 'patients' then
    if new.created_by is null then
      new.created_by := v_user_id;
    end if;
  elsif tg_table_name = 'invoices' then
    if new.created_by is null then
      new.created_by := v_user_id;
    end if;
  elsif tg_table_name = 'payments' then
    if new.collected_by is null then
      new.collected_by := v_user_id;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_treatment_status_from_visit_followup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_next_appointment_date timestamptz;
begin
  if new.visit_id is null then
    return new;
  end if;

  -- Only auto-decide the default Add Visit status. Manual status choices stay respected.
  if coalesce(new.status, 'planned') = 'planned' then
    select pv.next_appointment_date
      into v_next_appointment_date
    from public.patient_visits pv
    where pv.id = new.visit_id
      and pv.clinic_id = new.clinic_id;

    if v_next_appointment_date is not null then
      new.status := 'ongoing';
    else
      new.status := 'completed';
    end if;
  end if;

  return new;
end;
$function$
